const IM={};let loaded=0,N=Object.keys(SP).length;
for(const k in SP){const i=new Image();i.onload=()=>loaded++;i.src=SP[k];IM[k]=i}
const cv=document.getElementById('c');let g=cv.getContext('2d');g.imageSmoothingEnabled=false;
const T=32,W=48,H=36,VW=20,VH=14;
let seed=7;const rnd=()=>(seed=(seed*16807)%2147483647)/2147483647;
const SEAS=['Spring','Summer','Autumn','Winter'];
const CROPS={pear:{n:'Pear',s:[0,1],d:3,p:45},grape:{n:'Grape',s:[1,2],d:4,p:60},plum:{n:'Plum',s:[1],d:3,p:50},apple:{n:'Apple',s:[2,0],d:4,p:70}};
const CK=Object.keys(CROPS);
// ---------- world ----------
const map=[],solid=new Set(),deco=[];
const key=(x,y)=>x+','+y;
function gen(){seed=7;
 for(let y=0;y<H;y++){map[y]=[];for(let x=0;x<W;x++){let t=0;
  if(x>=20&&x<=22&&!(y>=16&&y<=17))t=1;if(x>=19&&x<=23&&x!=21&&(y==16||y==17))t=2;
  if(y>=14&&y<=16&&x>=22&&x<=30)t=t||3; if(x>=22&&x<=24&&y>=3&&y<=15)t=t||3;
  if(x>=24&&x<=44&&y>=9&&y<=10)t=t||3; map[y][x]=t}}
 for(let i=0;i<260;i++){const x=(rnd()*W)|0,y=(rnd()*H)|0;
  const woods=x>=24&&y>=18||x<2||y>33||x>45||y<1;
  if(!woods||map[y][x]||solid.has(key(x,y)))continue;
  if(x==40&&y==25||x>=43&&y>=29)continue;
  solid.add(key(x,y));deco.push({x,y,k:rnd()<.5?'tree':rnd()<.5?'pine':rnd()<.5?'stump':'log'})}
 for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(map[y][x]==1)solid.add(key(x,y));
 for(const b of [[4,19,3,2],[26,4,4,2],[41,22,0,0]])for(let i=0;i<b[2];i++)for(let j=0;j<b[3];j++)solid.add(key(b[0]+i,b[1]+j));
 // fence border
}
gen();
const LAN=[{n:'Hearth Lantern',x:9,y:22,need:'3 Pears + 5 Wood',chk:()=>S.inv.pear>=3&&S.inv.wood>=5,pay:()=>{S.inv.pear-=3;S.inv.wood-=5}},
 {n:'Brook Lantern',x:19,y:12,need:'4 Plums + 1 Jam',chk:()=>S.inv.plum>=4&&S.inv.jam>=1,pay:()=>{S.inv.plum-=4;S.inv.jam--}},
 {n:'Grove Lantern',x:40,y:25,need:'6 Mushrooms + 5 Grapes',chk:()=>mush()>=6&&S.inv.grape>=5,pay:()=>{S.inv.grape-=5;let n=6;for(const k of['m1','m2','m3','m4'])while(n&&S.inv[k]>0){S.inv[k]--;n--}}},
 {n:'Market Lantern',x:34,y:8,need:'400 gold + 2 Tarts',chk:()=>S.gold>=400&&S.inv.tart>=2,pay:()=>{S.gold-=400;S.inv.tart-=2}},
 {n:'Moon Shrine',x:44,y:31,need:'all four lit; face the Hollow',chk:()=>true,pay:()=>{}}];
const NPC=[{n:'Mayor Bram',x:25,y:8,c:'#c0603a',id:'b'},{n:'Pip',x:28,y:7,c:'#4a7fb0',id:'p'},{n:'Old Wren',x:36,y:21,c:'#8a5ab0',id:'w'},{n:'Maple',x:18,y:13,c:'#d0a030',id:'m'}];
const TALK={
b:[["Mayor Bram: Ah, you're Granny Wren's grandchild! The farm is yours now. But Lantern Woods is dimming...","Five lanterns keep the Woods calm. Light the Hearth Lantern by your house first: 3 pears and 5 wood. Press Q to switch tools, R to choose seeds."],
 ["Mayor Bram: The Hearth glows again! Next, the Brook Lantern by the river: 4 plums and a jar of jam. Cook jam at home with J."],
 ["Mayor Bram: The brook sings again. Now the Grove deep in the east woods: 6 mushrooms and 5 grapes."],
 ["Mayor Bram: Three lights! Our Market Lantern needs repair: 400 gold and 2 tarts. Cook tarts at home with T."],
 ["Mayor Bram: Four lanterns burn. Only the Moon Shrine remains, at the far southeast. Bring jam, tarts, and courage. Go at night."],
 ["Mayor Bram: The Woods are bright and so is the town. The farm is yours. Farm well!"]],
p:[["Pip: Welcome! Press E near me to sell everything. I sell seeds too: press 1-4 to buy pear, grape, plum, apple (30g)."]],
w:[["Old Wren: Your gran lit these lanterns every dusk. The Hollow sleeps below the shrine and feeds on dark. Remember that.","Old Wren: Foods cooked in lantern light hurt it, and heal you. Keep jam and tarts for the end."]],
m:[["Maple: I'm saving mushrooms in the grove. The woods have lots in autumn and spring!","Maple: Squirrels steal acorns, but the rose bushes by the brook keep them away. Probably."]]};
// ---------- state ----------
let S;function fresh(){return{x:6*T,y:24*T,d:1,day:1,min:360,gold:100,en:100,tool:0,seed:'pear',ch:0,lit:[0,0,0,0,0],hp:50,
 inv:{pear:0,grape:0,plum:0,apple:0,wood:0,jam:0,tart:0,bread:0,m1:0,m2:0,m3:0,m4:0,sp:3,sg:0,sl:0,sa:0},
 til:{},crop:{},forage:{},talk:{},won:0,log:[]}}
S=fresh();
try{const s=localStorage.getItem('lw1');if(s)S=Object.assign(fresh(),JSON.parse(s))}catch(e){}
let save=()=>{try{localStorage.setItem('lw1',JSON.stringify(S))}catch(e){}};
const mush=()=>S.inv.m1+S.inv.m2+S.inv.m3+S.inv.m4;
const season=()=>((S.day-1)/28|0)%4;
const sd=k=>'s'+k[0]; 
let msg='',msgT=0,dlg=null,mode='start',battle=null;
const say=t=>{msg=t;msgT=180};
const TOOLS=['Hoe','Watering can','Seeds','Axe'];
const keys={};addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(!keys[e.key])press(e.key);keys[e.key]=1});addEventListener('keyup',e=>keys[e.key]=0);
// ---------- gameplay ----------
function ft(){const dx=[0,1,0,-1][S.d],dy=[1,0,-1,0][S.d];return[((S.x+16)/T|0)+dx,((S.y+20)/T|0)+dy]}
function blocked(px,py){const tx=px/T|0,ty=py/T|0;if(tx<0||ty<0||tx>=W||ty>=H)return true;if(solid.has(key(tx,ty)))return true;if(S.crop[key(tx,ty)]&&0)return true;return NPC.some(n=>n.x==tx&&n.y==ty)||LAN.some(l=>l.x==tx&&l.y==ty)}
function newDay(){TC.slept=1;S.day++;S.min=360;S.en=100;S.hp=50+S.lit.reduce((a,b)=>a+b,0)*5;
 for(const k in S.crop){const c=S.crop[k];if(c.w){c.a++;c.w=0}}
 if(tut)for(const k in S.crop)S.crop[k].a=9;S.forage={};const wd=season()==3?4:16;
 for(let i=0;i<wd;i++){const x=24+(rnd()*20|0),y=19+(rnd()*14|0);if(!solid.has(key(x,y)))S.forage[key(x,y)]=['m1','m2','m3','m4'][rnd()*4|0]}
 for(const k in S.crop){const c=S.crop[k];if(season()==3)c.a=Math.max(0,c.a-1)}
 S.talk={};save();say('Day '+S.day+', '+SEAS[season()]+'. Rise and shine!')}
function press(k){
 if(mode!='play'&&mode!='battle'&&mode!='end'&&uiPress(k))return;
 if(mode=='end'){return}
 if(mode=='battle'){bkey(k);return}
 if(dlg){if(k=='e'||k==' '||k=='Enter'){if(dlgT<dlg[0].length){dlgT=999;return}dlg.shift();if(!dlg.length){dlg=null}}return}
 if(k=='Escape'){openMenu();return}
 const [fx,fy]=ft(),kk=key(fx,fy),i=S.inv;
 if(k=='q'||k=='Q')S.tool=(S.tool+1)%5;
 else if(k=='r'||k=='R'){let a=CK.indexOf(S.seed);S.seed=CK[(a+1)%4];say('Seed: '+CROPS[S.seed].n+' (owned '+i[sd(S.seed)]+')')}
 else if(k=='j'||k=='J'){if(near('home')){const f=CK.find(c=>i[c]>=2);if(f){i[f]-=2;i.jam++;TC.cook=1;say('Cooked jam!')}else say('Need 2 of one fruit.')}else say('Cook at your house.')}
 else if(k=='t'||k=='T'){if(near('home')){if(CK.reduce((a,c)=>a+i[c],0)>=3){let n=3;for(const c of CK)while(n&&i[c]>0){i[c]--;n--}i.tart++;say('Baked a tart!')}else say('Need 3 fruit.')}else say('Bake at your house.')}
 else if(k=='f'||k=='F'){if(near('home')&&i.wood>=1&&CK.some(c=>i[c]>=1)){i.wood--;const c=CK.find(c=>i[c]>=1);i[c]--;i.bread++;say('Baked bread (+20 HP in battle).')}else say('Need wood + fruit at home.')}
 else if(k=='Enter'){const n=NPC.find(n=>Math.abs(n.x*T-S.x)<56&&Math.abs(n.y*T-S.y)<56);if(n)talk(n);else if(inHouse(fx,fy))openHome();else interact(fx,fy,kk)}
 else if(k=='e'||k==' ')act(fx,fy,kk);
 if(['1','2','3','4','5'].includes(k)&&!near('shop'))S.tool=+k-1;
 if(['1','2','3','4'].includes(k)&&near('shop')){const c=CK[+k-1];if(S.gold>=30){S.gold-=30;i[sd(c)]++;say('Bought '+CROPS[c].n+' seed.')}else say('Not enough gold.')}
 if(k=='m')say('Day '+S.day+' '+SEAS[season()]+' | Lanterns: '+S.lit.reduce((a,b)=>a+b,0)+'/5')}
function newDay0(){S.day--;newDay()}
const near=w=>{const px=S.x/T,py=S.y/T;if(w=='home')return Math.abs(px-5.5)<4&&Math.abs(py-20.5)<4;if(w=='shop')return Math.abs(px-28)<5&&Math.abs(py-7)<4;return false};
function talk(n){const L=TALK[n.id],st=n.id=='b'?Math.min(S.ch,5):0;let d=L[Math.min(st,L.length-1)].slice();
 if(n.id=='p'){sellAll();return}
 if(n.id=='b'&&S.ch==5&&!S.won)d=["Mayor Bram: The Hollow awaits at the shrine. Go at night."];
 if(n.id=='b'&&S.won)d=TALK.b[5];dlg=d}
function sellAll(){TC.sold=1;let t=0,i=S.inv;for(const c of CK){t+=i[c]*CROPS[c].p;i[c]=0}for(const m of['m1','m2','m3','m4']){t+=i[m]*25;i[m]=0}t+=i.jam*130;i.jam=0;
 dlg=t?["Pip: Deal! "+t+" gold for your goods. (Tip: keep a few jam and tarts for the shrine.)"]:["Pip: Nothing to sell? Press 1-4 to buy seeds (30g)."];S.gold+=t}
function interact(fx,fy,kk){const l=LAN.findIndex(l=>Math.abs(l.x-fx)<=1&&Math.abs(l.y-fy)<=1);if(l>=0)lantern(l)}
function lantern(l){const L=LAN[l];if(S.lit[l]){say(L.n+' is burning.');return}
 if(l!=S.ch){say(l>S.ch?'It is too dark. Light the earlier lanterns first.':'');return}
 if(l==4){if(S.min<18*60){say('The Hollow sleeps by day. Return after 6 PM.');return}startBattle();return}
 if(L.chk()){L.pay();S.lit[l]=1;S.ch++;S.hp+=5;dlg=[L.n+' flares to life! Warmth floods the woods.',['The Hearth warms the old farm. A path of fireflies leads toward the brook.','The Brook runs silver. Maple whoops from the bank.','The Grove rustles awake. The mushrooms glow softly.','The Market Lantern hums. Only the Moon Shrine remains.'][l]];save()}
 else dlg=[L.n+' needs: '+L.need+'.']}
function act(fx,fy,kk){startAct(kk);const i=S.inv;
 // sleep at bed
 if(fx>=4&&fx<=6&&fy==21&&near('home')){if(S.min>=18*60||S.en<30||tut){newDay();return}say('Too early to sleep (after 6 PM or when tired).');return}
 if(S.tool==4&&inHouse(fx,fy)){openHome();return}
 const nl=LAN.findIndex(l=>Math.abs(l.x-fx)<=0&&Math.abs(l.y-fy)<=0);if(nl>=0){lantern(nl);return}
 const kp=KP[kk];if(kp&&!S.kept[kp]){S.kept[kp]=1;S.gold+=40;say('Keepsake found! '+Object.keys(S.kept).length+'/'+cells('keepsakes').length+' (+40g)');return}
 if(S.forage[kk]){i[S.forage[kk]]++;delete S.forage[kk];say('Foraged!');return}
 if(S.en<2){say('Too tired. Go to bed.');return}
 const c=S.crop[kk];
 if(c&&c.a>=CROPS[c.k].d&&S.tool!=3){TC.harv=1;i[c.k]++;if(CROPS[c.k].d>0){c.a=1;c.k0=1}if(!CROPS[c.k].reg){delete S.crop[kk]}S.en-=1;say('Harvested '+CROPS[c.k].n+'!');return}
 const t=S.tool;
 if(t==0){if(solid.has(kk)||map[fy]?.[fx]||fx<2||fx>18||fy<18||fy>33){say('Cannot till here. Use the farm plot.');return}S.til[kk]=1;TC.till=1;S.en-=2}
 else if(t==1){if(S.crop[kk]){S.crop[kk].w=1;TC.water=1;S.en-=1;say('Watered.')}else say('Nothing to water.')}
 else if(t==2){if(!S.til[kk]||S.crop[kk]){say('Plant on tilled, empty soil.');return}const s=S.seed;if(!CROPS[s].s.includes(season())){say(CROPS[s].n+' cannot grow in '+SEAS[season()]+'.');return}if(i[sd(s)]<1){say('No '+CROPS[s].n+' seeds. Buy from Pip.');return}i[sd(s)]--;TC.plant=1;S.crop[kk]={k:s,a:0,w:0}}
 else if(t==3){const d=deco.findIndex(d=>d.x==fx&&d.y==fy);if(d>=0){const o=deco[d];i.wood+=o.k=='tree'||o.k=='log'||String(o.k).startsWith('treetypes')?3:o.k=='pine'?2:1;solid.delete(kk);deco.splice(d,1);S.en-=3;say('+Wood')}}}
// ---------- battle ----------
function startBattle(){mode='battle';battle={hp:S.hp,boss:70,t:0,log:['The Hollow rises from the dark!'],cd:0,over:0}}
function bkey(k){const b=battle,i=S.inv;if(b.over){if(k=='Enter'||k==' '||k=='e'){if(b.over==2){S.hp=50;S.min=360;newDay();mode='play'}else{S.ch=5;S.won=1;S.lit[4]=1;S.gold+=1000;mode='end';save()}}return}
 let used=0;const L=S.lit.reduce((a,b)=>a+b,0);
 if(k=='1'){const d=8+L+(rnd()*6|0);b.boss-=d;b.log=['You strike for '+d+'!'];used=1}
 else if(k=='2'&&i.jam>0){i.jam--;b.hp=Math.min(60,b.hp+18);b.log=['Jam warms you: +18 HP.'];used=1}
 else if(k=='3'&&i.tart>0){i.tart--;b.hp=Math.min(60,b.hp+35);b.log=['Tart heals you: +35 HP.'];used=1}
 else if(k=='4'&&b.cd<=0){b.boss-=28;b.cd=3;b.log=['Lantern burst! 28 damage.'];used=1}
 else if(k=='5'&&i.bread>0){i.bread--;b.hp=Math.min(60,b.hp+20);b.log=['Bread: +20 HP.'];used=1}
 if(!used)return;b.cd--;
 if(b.boss<=0){b.log.push('The Hollow dissolves into soft light.');b.over=1;return}
 b.t++;const d=b.t%4==0?20:5+(rnd()*8|0);b.hp-=d;b.log.push('The Hollow lashes out: -'+d+' HP.');
 if(b.hp<=0){b.log.push('You fade...');b.over=2}}
// ---------- loop ----------
