function txt(s,x,y,sz=13,c=UI.txt,al='left',b=0){g.font=(b?'bold ':'')+sz+'px monospace';g.fillStyle=c;g.textAlign=al;g.fillText(s,x,y);g.textAlign='left'}
function box(x,y,w,h,title){g.fillStyle='rgba(0,0,0,.4)';g.fillRect(x+3,y+4,w,h);g.fillStyle=UI.pan;g.beginPath();g.roundRect?g.roundRect(x,y,w,h,8):g.rect(x,y,w,h);g.fill();g.strokeStyle=UI.edge;g.lineWidth=2;g.stroke();g.strokeStyle='#8a6a2a';g.lineWidth=1;g.strokeRect(x+5,y+5,w-10,h-10);g.lineWidth=1;if(title){g.fillStyle=UI.pan2;g.fillRect(x+12,y-9,g.measureText(title).width+30,18);txt(title,x+20,y+4,13,UI.edge,'left',1)}}
function key2(s,x,y){g.font='bold 12px monospace';const w=g.measureText(s).width+14;g.fillStyle='#e9dcb5';g.fillRect(x,y,w,22);g.fillStyle='#8a7a50';g.fillRect(x,y+19,w,4);txt(s,x+7,y+15,12,'#2a1a0a','left',1);return w+6}
function bar(x,y,w,v,c,lab){g.fillStyle='#1a1008';g.fillRect(x,y,w,9);g.fillStyle=c;g.fillRect(x+1,y+1,Math.max(0,(w-2)*Math.min(1,v)),7);txt(lab,x+w+5,y+9,10,UI.dim)}
