const BB={};
function bbox(k){const key=AL[k]||k;if(BB[key])return BB[key];const i=IM[key];if(!i||!i.complete)return null;let r=[0,0,64,64];try{const c=document.createElement('canvas');c.width=c.height=64;const q=c.getContext('2d');q.drawImage(i,0,0,64,64);const d=q.getImageData(0,0,64,64).data;let x0=64,y0=64,x1=-1,y1=-1;for(let y=0;y<64;y++)for(let x=0;x<64;x++)if(d[(y*64+x)*4+3]>16){if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y}if(x1>=0)r=[x0,y0,x1-x0+1,y1-y0+1]}catch(e){}return BB[key]=r}
function sprFit(k,x,y,s,max){const b=bbox(k),i=IM[AL[k]||k];if(!b||!i)return;const sc=Math.min(s/b[2],s/b[3],max||99),w=b[2]*sc,h=b[3]*sc;g.drawImage(i,b[0],b[1],b[2],b[3],x+(s-w)/2,y+(s-h)/2,w,h)}
function wrapT(s,x,y,w,sz,col,lh,max){g.font=sz+'px monospace';g.fillStyle=col;g.textAlign='left';let l='',n=0;for(const t of s.split(' ')){if(g.measureText(l+t).width>w){g.fillText(l,x,y);y+=lh;l='';if(++n>=max)return y}l+=t+' '}g.fillText(l,x,y);return y+lh}
