let AL2={s:0,sc:0,ls:0},ALW=null;
function almWrap(){if(ALW)return;ALW=ALM.map(s=>{const out=[];g.font='11px monospace';for(const raw of s.b.split('\n')){if(!raw){out.push('');continue}let l='';for(const w of raw.split(' ')){if(g.measureText(l+w).width>400){out.push(l);l='   '+(w)+' '}else l+=w+' '}out.push(l)}return out})}
function almOpen(from){almFrom=from;mode='alm';AL2.sc=0;almWrap()}
function almKey(k){const n=ALM.length;
 if(k=='Escape'){mode=almFrom=='fg'?'fg':almFrom=='start'?'start':'menu';return}
 if(k=='ArrowDown'||k=='s')AL2.sc+=3;else if(k=='ArrowUp'||k=='w')AL2.sc=Math.max(0,AL2.sc-3);
 else if(k=='PageDown')AL2.sc+=15;else if(k=='PageUp')AL2.sc=Math.max(0,AL2.sc-15);
 else if(k=='ArrowRight'||k=='d'||k=='e'){AL2.s=(AL2.s+1)%n;AL2.sc=0}else if(k=='ArrowLeft'||k=='a'||k=='q'){AL2.s=(AL2.s+n-1)%n;AL2.sc=0}
 else if(k=='Home')AL2.sc=0;
 almFix()}
