const CRK=Object.keys(CR);const SEEDS5=[...CRK,'grass'];const SN=k=>k=='grass'?'Grass':CR[k].n;const cn=(k,n=1)=>{FG.cnt=FG.cnt||{};FG.cnt[k]=(FG.cnt[k]|0)+n};
const PRICE={turnip:60,potato:80,tomato:100,corn:120,egg:50,milkS:150,milkM:250,milkL:350,grapes:150,mush:150,herb:200,fruit:200,fish:300,pmush:200,berry:600};
