 lib:[{n:'Librarian',c:'#5a6a8a',h:'#4a3020',act:'read',zone:'row',L:['Librarian: Shhh. I am reading. Shhh is also a reading.']},{n:'Reader',c:'#8a6a4a',h:'#c8a050',act:'read',at:[6,9],L:['Reader: I have been on this page since Tuesday. It is good.']}],
