const INR={};
function iList(){const id=FG.inId,L=(INPL[id]||[]).filter(p=>!p.night||FG.min>=1080).map(p=>Object.assign({},p));
 if(id=='house'){if(FG.married>=0&&!FG.left&&FG.day>=FG.wedDay){const g_=GIRLS[FG.married];L.push({n:g_.n,c:g_.c,h:g_.h,act:'sweep',zone:'house',wife:1,L:[g_.n+': Welcome home. I did the watering. Please acknowledge my competence.']})}
  for(let k=0;k<Math.min(2,FG.kids|0);k++)L.push({n:'Kid',c:['#e8c040','#58a0d8'][k],h:['#6a3a1a','#c8a050'][k],act:'',zone:'house',kid:1,L:['Kid: Hi. I am small. I have a stick.']})}
 return L}
function iInit(){const key=FG.inId+'|'+FG.day+'|'+(FG.min>=1080?1:0)+'|'+FG.kids+'|'+FG.married+'|'+FG.left;if(INR.key==key)return;INR.key=key;INR.list=iList().map((p,i)=>{let x,y;if(p.at){x=p.at[0];y=p.at[1]}else if(p.zone=='house'){x=7+i;y=7}else if(p.zone=='left'){x=6;y=5}else if(p.zone=='right'){x=12;y=5}else{x=8+(i%3);y=5}return Object.assign(p,{x:x*32,y:y*32,d:0,path:[],t:Math.random()*3,walk:0})})}
function iSpots(p){if(p.zone=='row')return[[7,5],[8,5],[9,5],[10,5],[11,5],[12,5]];if(p.zone=='left')return[[5,5],[6,5],[7,5]];if(p.zone=='right')return[[11,5],[12,5],[13,5]];if(p.zone=='house')return[[5,7],[8,7],[10,7],[9,9],[5,9],[10,9],[8,9]];return null}
let iLast=0;
function iUpdate(){iInit();const now=performance.now(),dt=Math.min(.06,(now-(iLast||now))/1000);iLast=now;
 for(const p of INR.list){p.walk=0;const tx=Math.round(p.x/32),ty=Math.round(p.y/32);
  if(p.path.length){const[px,py]=p.path[0],X=px*32,Y=py*32,dx=X-p.x,dy=Y-p.y,sp=(p.kid?50:30)*dt,L=Math.hypot(dx,dy);const nx=L<sp?X:p.x+dx/L*sp,ny=L<sp?Y:p.y+dy/L*sp;
   const hit=!(nx+26<FG.x+8||nx+6>FG.x+24||ny+32<FG.y+20||ny+12>FG.y+30);if(!hit){p.x=nx;p.y=ny;p.walk=1;if(Math.abs(dx)>Math.abs(dy))p.d=dx>0?1:3;else p.d=dy>0?0:2;if(L<sp+.01)p.path.shift()}}
  else{p.t-=dt;const near=Math.hypot(p.x-FG.x,p.y-FG.y)<80;if(near){const dx=FG.x-p.x,dy=FG.y-p.y;p.d=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2)}else if(!p.at)p.d=p.zone=='house'?p.d:0;
   if(p.t<=0){p.t=2.5+Math.random()*4;const sp=iSpots(p);if(sp){const c=sp[(Math.random()*sp.length)|0],pa=fpath(tx,ty,c[0],c[1]);if(pa){pa.shift();p.path=pa}}}}}}
function iRects(){iInit();return INR.list.map(p=>[p.x+6,p.y+12,p.x+26,p.y+32])}
function iTalk(){iInit();const[tx,ty]=fgFace();for(const p of INR.list){if(Math.round(p.x/32)==tx&&Math.round(p.y/32)==ty||Math.abs(p.x-FG.x)<40&&Math.abs(p.y-FG.y)<40&&Math.abs(p.x/32-tx)<1.2&&Math.abs(p.y/32-ty)<1.2){p.path=[];p.t=3;const dx=FG.x-p.x,dy=FG.y-p.y;p.d=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);return p.L}}return null}
function iDraw(t){iInit();const L=INR.list.slice().sort((a,b)=>a.y-b.y);for(const p of L){if(p.kid){g.save();g.translate(Math.round(p.x)+4,Math.round(p.y)+9);g.scale(.72,.72);figX(p,p,0,0,t,-1);g.restore()}else figX(p,p,Math.round(p.x),Math.round(p.y),t,-1)}}
