function fq(){const i=FG.ch|0;return QUESTS[i]||null}
function fqCheck(){const q=fq();if(!q||FG.qready)return;if(FG.day<2)return;try{if(q.ok()){FG.qready=1;fsay('Goal done: '+q.t+'. Check the mailbox!')}else if(q.by&&FG.day>q.by){FG.ch=(FG.ch|0)+1;fsay('Missed: '+q.t+'. The guide shrugs. Next goal.')}}catch(e){}}
function fmail(){const q=fq();
 if(q&&FG.qready){const lines=q.l.slice();FG.gold+=q.r;FG.ch=(FG.ch|0)+1;FG.qready=0;fdlg(lines,()=>{const n=fq();fsay(n?'New objective: '+n.o:'You followed the whole guide. Frame it.')});return}
 const P=['Postcard: "Wish you were here. We are here. It is lovely. Have you done anything yet?"','Postcard: "The buffet had a chocolate fountain. Of course it did. Have you tried a turnip?"','Postcard: "Captain says the iceberg was \'a surprise.\' Everyone is fine."','Postcard: "We sent you a snow globe. It is of us. Display it."','Postcard: "The cruise has a casino. We have, regrettably, learned about odds."'];
 fdlg([P[FG.day%P.length],q?'Objective: '+q.o:'Every chapter of the guide followed. Frame the Almanac.'])}
function fqlog(){const c=FG.ch|0,lo=Math.max(0,Math.min(c-2,QUESTS.length-6)),o=[];for(let i=lo;i<Math.min(QUESTS.length,lo+6);i++)o.push({t:(i<c?'[x] ':i==c?'[>] ':'[ ] ')+(i<=c?QUESTS[i].t:'???'),go:fclose});if(QUESTS[c])o.push({t:'Goal: '+QUESTS[c].o.slice(0,40),go:fclose});o.push({t:'Chapters done: '+c+'/'+QUESTS.length,go:fclose});fmenu('Quest log: The Guide',o,Math.min(c-lo,o.length-1))}
function fcook(){if((FG.inv.egg||0)<1||!(FG.inv.milkS||FG.inv.milkM||FG.inv.milkL)){fsay('Cake needs 1 egg and 1 milk.');return}const m=FG.inv.milkS?'milkS':FG.inv.milkM?'milkM':'milkL';FG.inv.egg--;FG.inv[m]--;FG.inv.cake=(FG.inv.cake||0)+1;fsay('You baked a Cake. It is slightly on fire. Cake +1.')}
