function slotLbl(n){const s=slotGet(n);if(!s)return 'Slot '+n+': (empty)';const d=s.data;return 'Slot '+n+': '+SEAS4[sdy(d.day)]+' '+dom(d.day)+' Y'+yr(d.day)+' · '+d.gold+'g'+(d.married>=0?' · married':'')}
function fsnap(){const c=Object.assign({},FG);delete c.ui;delete c.hunt;delete c.last;return c}
function slotSave(n){try{localStorage.setItem('lwslot'+n,JSON.stringify({t:Date.now(),data:fsnap()}));fgSave();return true}catch(e){return false}}
function fApply(d){for(const k in FG)delete FG[k];Object.assign(FG,fgFresh(),d);FG.on=true;FG.ui=null;FG.ended=0;mode='fg';FG.last=performance.now();FG.cnt=FG.cnt||{};FG.tour=FG.tour||{};FG.flags=FG.flags||{};fgFore();if(FG.sc=='in'){try{iInit()}catch(e){}}fgSave()}
function fslotLoad(n){const s=slotGet(n);if(!s){fsay('Slot '+n+' is empty.');return}fApply(s.data);fsay('Loaded slot '+n+'.')}
function fslots(kind,fromStart){const o=[];for(let i=1;i<=NSLOT;i++){const n=i;o.push({t:slotLbl(n),go:()=>{if(kind=='save'){fclose();fsay(slotSave(n)?'Saved to slot '+n+'.':'Could not save (storage blocked).')}else{if(!slotGet(n)){fsay('Slot '+n+' is empty.');return}fslotLoad(n)}}})}
 if(kind=='load'&&hasFull())o.push({t:'Autosave (latest)',go:()=>{fgLoad()}});
 if(fromStart){o.push({t:'Import save from file',go:fimport})}
 o.push({t:fromStart?'Back':'Cancel',go:()=>{if(fromStart){FG.ui=null;mode='start'}else fclose()}});
 fmenu(kind=='save'?'Save Game':'Load Game',o,0)}
function fLoadScreen(){const o=fgFresh();for(const k in FG)delete FG[k];Object.assign(FG,o);FG.on=true;mode='fg';FG.last=performance.now();fgFore();fslots('load',true)}
function fexport(){const txt=JSON.stringify({lw:1,data:fsnap()});fclose();
 const fb=()=>{try{const b=new Blob([txt],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='lantern_woods_save.json';document.body.appendChild(a);a.click();setTimeout(()=>{try{a.remove()}catch(e){}},500);fsay('Save file downloaded.')}catch(e){fsay('Export is not available here.')}};
 try{if(window.claude&&claude.use){claude.use('downloads').then(d=>{if(!d){fb();return}d.save({filename:'lantern_woods_save.json',data:txt}).then(()=>fsay('Save file saved.')).catch(e=>fsay(e&&e.code=='declined'?'Export cancelled.':'Export is not available here.'))}).catch(fb);return}}catch(e){}
 fb()}
function fimport(){try{const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=()=>{const f=i.files&&i.files[0];if(!f)return;const r=new FileReader();r.onload=()=>fimportText(String(r.result));r.readAsText(f)};i.click()}catch(e){fsay('Import is not available here.')}}
function fimportText(t){try{const o=JSON.parse(t),d=o&&o.data;if(!d||typeof d.day!='number'||!d.land||!d.cows)throw 0;fApply(d);fsay('Save imported.')}catch(e){fsay('That is not a Lantern Woods save file.')}}
// ---- edge hints: tell the player what to do when the map will not let them leave
function fhintText(){const sc=FG.sc;
 if(FG.day==1&&!ftourOK()){const un=(ftour().match(/\[ \] \w+/g)||[]).map(s=>s.slice(4));return['The Shipper blocks the exit. Still to meet: '+un.join(', ')+'.','Find them around town and press E next to each. Their shops are the buildings.']}
 if(FG.day==1)return['Everyone met! Walk back to the Shipper (far west of town) and press E.','He will take you home to start Day 2.'];
 const q=fq(),ex=sc=='ranch'?'Town is east.':sc=='town'?'Ranch is west, the Mountain is up in the north-east corner.':'Town is south.';
 return['This is the edge of the map. '+ex,q?(FG.qready?'Goal done! Check the mailbox on your ranch to claim the reward.':'Your goal: '+q.o):'Follow the Almanac (Esc) for ideas.']}
function fhint(){if(FG.hintCool>0)return;FG.hint=fhintText();FG.hintT=260;FG.hintCool=90}
const ft9=ftrans;ftrans=function(){const sc0=FG.sc,d1=FG.day==1&&sc0=='town'&&(FG.x<-6||FG.y<-6);ft9();
 if(FG.sc!=sc0||FG.ui||FG.sc=='in')return;const T=32;
 if(d1){fhint();return}
 const e=FG.x<=-6||FG.x>=20*T-14||FG.y<=-6||(FG.sc=='town'&&FG.y>=11*T)||(FG.sc=='ranch'&&FG.y>=12*T-12);if(e)fhint()};
const fdH=fgDraw;fgDraw=function(t){fdH(t);if(FG.hintCool>0)FG.hintCool--;
 if(FG.hintT>0){FG.hintT--;if(FG.ui||!FG.hint)return;g.globalAlpha=Math.min(1,FG.hintT/30);g.fillStyle='rgba(20,12,4,.88)';const ls=[];let c='';for(const w of FG.hint.join(' ').split(' ')){if((c+w).length>66){ls.push(c);c=''}c+=w+' '}ls.push(c);const hh=12+ls.length*16,y0=380-hh;g.fillRect(50,y0,540,hh);g.strokeStyle=UI.edge;g.strokeRect(50.5,y0+.5,539,hh-1);txt('HINT',60,y0+16,10,UI.edge);ls.forEach((l,i)=>txt(l,100,y0+16+i*16,11,'#fff'));g.globalAlpha=1}};

// ===== v8h: Bot speed-run demo (one week of the Full Game) =====
const BOT={total:4500,fps:60,lt:0,n:0,acc:0,on:0,gen:null,speed:3,paused:0,cap:'',done:0,int:0,dw:14,tacc:0};
function bk(k){BOT.int=1;try{fgKey(k)}finally{BOT.int=0}}
function bcap(t){BOT.cap=t}
function btime(n){BOT.tacc+=n;const w=Math.floor(BOT.tacc);if(w>0){BOT.tacc-=w;FG.min=Math.min(1380,FG.min+w)}}
function* bwait(n){for(let i=0;i<n;i++)yield}
function* bdlg(){let g=0;while(FG.ui&&FG.ui.t=='dlg'&&g++<120){yield* bwait(BOT.dw);if(!FG.ui||FG.ui.t!='dlg')break;bk('Enter');yield* bwait(5);if(FG.ui&&FG.ui.t=='dlg')bk('Enter')}yield* bwait(4)}
function* bmenu(re){let g=0;while(!(FG.ui&&FG.ui.t=='menu')&&g++<30)yield;if(!(FG.ui&&FG.ui.t=='menu'))return false;
 const i=FG.ui.opts.findIndex(o=>re.test(o.t));if(i<0){FG.ui=null;return false}FG.ui.sel=i;yield* bwait(14);const o=FG.ui.opts[i];o.go();yield* bwait(6);return true}
function bpos(){return[Math.floor((FG.x+16)/32),Math.floor((FG.y+24)/32)]}
function bbfs(pred){const[sx,sy]=bpos(),q=[[sx,sy]],seen={[sx+','+sy]:null};let h=0;
 while(h<q.length){const[x,y]=q[h++];if(pred(x,y)){const p=[];let k=x+','+y;while(seen[k]!==null){const[a,b]=k.split(',').map(Number);p.unshift([a,b]);k=seen[k]}return p}
  for(const[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=nx+','+ny;if(k in seen||fsolid(nx,ny)||(FG.sc!='in'&&fdoorOf(nx,ny)))continue;seen[k]=x+','+y;q.push([nx,ny])}}return null}
function* bwalkPath(p){for(const[tx,ty]of p){const dx=tx*32-FG.x,dy=ty*32-FG.y;FG.d=Math.abs(dx)>=Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);
  let g=0;while((Math.abs(tx*32-FG.x)>.5||Math.abs(ty*32-FG.y)>.5)&&g++<40){const sx=Math.sign(tx*32-FG.x),sy=Math.sign(ty*32-FG.y);FG.x+=sx*Math.min(8,Math.abs(tx*32-FG.x));FG.y+=sy*Math.min(8,Math.abs(ty*32-FG.y));yield}
  FG.x=tx*32;FG.y=ty*32;btime(.35)}}
// walk to a tile next to tile (tx,ty) and face it
function* bnear(tx,ty,rect){const adj=(x,y)=>rect?[[1,0],[-1,0],[0,1],[0,-1]].some(([a,b])=>{const X=x+a,Y=y+b;return X>=rect.x&&X<rect.x+rect.w&&Y>=rect.y&&Y<rect.y+rect.h})&&!(x>=rect.x&&x<rect.x+rect.w&&y>=rect.y&&y<rect.y+rect.h):Math.abs(x-tx)+Math.abs(y-ty)==1;
 const p=bbfs(adj);if(!p){return false}yield* bwalkPath(p);const[cx,cy]=bpos();let T=[tx,ty];
 if(rect){for(const[a,b]of[[0,1],[1,0],[0,-1],[-1,0]]){const X=cx+a,Y=cy+b;if(X>=rect.x&&X<rect.x+rect.w&&Y>=rect.y&&Y<rect.y+rect.h){T=[X,Y];break}}}
 const dx=T[0]-cx,dy=T[1]-cy;FG.d=dy>0?0:dx>0?1:dy<0?2:3;yield* bwait(4);return true}
function* bpress(fb){const t0=FG.toast,u0=FG.ui;bk('e');yield* bwait(4);btime(3);if(!FG.ui&&FG.toast==t0&&fb)fb();yield* bwait(6)}
function* bto(x,y){const p=bbfs((a,b)=>a==x&&b==y);if(p)yield* bwalkPath(p)}
function* bleave(){yield* bto(9,10);FG.y=10*32+24;ftrans();yield* bwait(8)}
function* bgo(sc){let g=0;while(FG.sc!=sc&&g++<8){if(FG.sc=='in'){yield* bleave();continue}
  const s=FG.sc,toTown=(s=='ranch'||(s=='mtn'));
  if(s=='ranch'){const p=bbfs((x,y)=>x==19);if(p)yield* bwalkPath(p);FG.x=20*32-10;ftrans()}
  else if(s=='town'&&sc=='mtn'){const p=bbfs((x,y)=>y==0&&x>=18);if(p)yield* bwalkPath(p);FG.y=-8;ftrans()}
  else if(s=='town'){const p=bbfs((x,y)=>x==0);if(p)yield* bwalkPath(p);FG.x=-8;ftrans()}
  else if(s=='mtn'){const p=bbfs((x,y)=>y==12&&x>=9&&x<=11);if(p)yield* bwalkPath(p);FG.y=12*32+16;ftrans()}
  yield* bwait(10)}}
function* benter(id){const o=OB[FG.sc].find(o=>o.id==id);const a=doorA(o);yield* bto(a,o.y+o.h);FG.d=2;yield* bwait(4);yield* bwalkPath([[a,o.y+o.h-1]].filter(()=>false));FG.y-=16;yield* bwait(3);fenter(o);yield* bwait(8)}
function* bstation(act){const f=ffurn().find(f=>f.act==act);yield* bnear(0,0,f)}
function* bobj(id){const o=OB[FG.sc].find(o=>o.id==id);yield* bnear(0,0,o);yield* bpress(()=>fobj(o))}
function* bsleep(){yield* bgo('ranch');yield* benter('house');yield* bstation('sleep');yield* bpress(()=>fin());yield* bmenu(/Sleep/);yield* bwait(10);yield* bdlg()}
function* bdoors(){yield* bdlg()}
function bland(t){const o=[];for(let y=3;y<=9;y++)for(let x=2;x<=11;x++){const k=x+','+y;if(FG.land[k]==t&&!FG.crop[k])o.push([x,y])}return o}
function* bwork(tool,type,n){let done=0,g=0;while(done<n&&g++<60){const L=bland(type);if(!L.length)break;const[sx,sy]=bpos();L.sort((a,b)=>Math.abs(a[0]-sx)+Math.abs(a[1]-sy)-Math.abs(b[0]-sx)-Math.abs(b[1]-sy));
  let ok=false;for(const[x,y]of L.slice(0,4)){FG.tool=tool;ok=yield* bnear(x,y);if(ok){const k=x+','+y,l0=FG.land[k];yield* bpress();if(FG.land[k]!=l0||FG.crop[k])done++;break}}if(!ok)break}return done}
function* bwater(){const ks=Object.keys(FG.crop);for(const k of ks){const[x,y]=k.split(',').map(Number);FG.tool=1;if(yield* bnear(x,y)){yield* bpress()}}}
function* bplant(n,sk){FG.seedSel=SEEDS5.indexOf(sk);let d=0;for(const k of bland('till').slice(0,n)){const[x,y]=k;FG.tool=8;if(yield* bnear(x,y)){yield* bpress();d++}}return d}
function* bshop(id,buys){yield* bgo('town');yield* benter(id);yield* bnear(0,0,ffurn().find(f=>f.act=='shop'));yield* bpress(()=>fobj(FG.ob));yield* bdlg();
 for(const b of buys||[]){if(yield* bmenu(b)){}}if(FG.ui&&FG.ui.t=='menu')yield* bmenu(/Leave|Cancel/);yield* bdlg();yield* bleave()}
function* btalk(i,chat){yield* bgo('town');const p=npcPos(i);if(!p)return;const x=Math.round(p.x),y=Math.round(p.y);const ok=yield* bnear(x,y);yield* bpress(()=>ftalk(i));if(!(FG.ui&&FG.ui.t=='menu'))ftalk(i);
 yield* bmenu(chat?/Chat/:/Leave/);yield* bdlg();if(FG.ui&&FG.ui.t=='menu')yield* bmenu(/Leave/)}
function* bmorning(){yield* bwait(20);yield* bdlg();if(FG.sc=='in')yield* bleave();yield* bdlg()}
function* bclaim(){fqCheck();yield* bobj('mail');yield* bdlg()}
function bsum(){const q=Math.min(FG.ch|0,QUESTS.length);return['WEEK ONE COMPLETE. The bot did everything the Almanac asked.','Gold '+FG.gold+'g · guide goals done '+q+'/'+QUESTS.length+' · turnips shipped '+(FG.st2.shipped|0)+' · dog Koro acquired (useless, loyal).','The game continues for 4 more years and 9 more endings. Your move, human.']}
function* bscript(){
 bcap('Prologue: a deed, a key, and a note');yield* bwait(30);yield* bdlg();
 // DAY 1
 bcap('DAY 1: Tour of town. Meet Ned and Hugh, then Marlowe, Annika, Nadia and Evie.');
 yield* bshop('seeds');bcap('DAY 1: Hugh Moo at the barn dealer (free grass seed)');yield* bshop('dealer');
 bcap('DAY 1: Talk to the girls (and Evie)');for(const i of[0,1,2,4])yield* btalk(i,i==0);
 bcap('DAY 1: Back to the Shipper. He agrees to leave.');{const p=bbfs((x,y)=>x==2&&y==6);if(p)yield* bwalkPath(p);FG.d=3;yield* bwait(6);yield* bpress(()=>fshipper());yield* bmenu(/Take me home/);yield* bdlg()}
 // DAY 2
 bcap('DAY 2: Meet Koro the dog (not optional)');yield* bwait(20);yield* bdlg();yield* bmorning();
 bcap('DAY 2: Guide goal 1. Cut 15 fodder with the sickle.');yield* bwork(2,'grass',15);
 bcap('DAY 2: Chop 2 stumps with the axe.');yield* bwork(3,'stump',2);
 bcap('DAY 2: Smash 1 stone with the hammer.');yield* bwork(4,'stone',1);
 bcap('DAY 2: Sleep. Time passes whether you like it or not.');yield* bsleep();
 // DAY 3
 bcap('DAY 3: Claim the postcard reward at the mailbox.');yield* bmorning();yield* bclaim();
 bcap('DAY 3: Buy turnip seeds at Ned\'s (40g each).');yield* bshop('seeds',[/Turnip seeds/,/Turnip seeds/,/Turnip seeds/,/Turnip seeds/,/Turnip seeds/]);
 bcap('DAY 3: Say hi to Marlowe. She tells everyone about your turnips.');yield* btalk(0,true);
 bcap('DAY 3: Back on the ranch: till 8 tiles with the hoe.');yield* bgo('ranch');yield* bwork(0,'soil',8);
 bcap('DAY 3: Plant 4 turnips, then water them.');yield* bplant(4,'turnip');yield* bwater();
 bcap('DAY 3: Sleep.');yield* bsleep();
 // DAY 4
 bcap('DAY 4: Water, then check the mailbox for guide goal 2.');yield* bmorning();yield* bwater();yield* bclaim();
 bcap('DAY 4: Mountain trip: cave herb.');yield* bgo('mtn');{const o=OB.mtn.find(o=>o.id=='cave');yield* bnear(0,0,o);yield* bpress(()=>fobj(o))}yield* bdlg();
 bcap('DAY 4: Hot spring. Five jumps heal everything.');{const o=OB.mtn.find(o=>o.id=='springs');yield* bnear(0,0,o);yield* bpress(()=>fobj(o))}
 bcap('DAY 4: Home and sleep.');yield* bsleep();
 // DAY 5
 bcap('DAY 5: Water the turnips.');yield* bmorning();yield* bwater();
 bcap('DAY 5: Friendship day. Chat with Nadia and Annika, buy a flower.');yield* btalk(2,true);yield* btalk(1,true);yield* bshop('flowers',[/Flower/]);
 bcap('DAY 5: Sleep.');yield* bsleep();
 // DAY 6
 bcap('DAY 6: Water the turnips. One more day.');yield* bmorning();yield* bwater();
 bcap('DAY 6: Browse the Library (Almanac) and the Church calendar.');yield* bshop('lib',[/Leave/]);yield* bshop('church',[/Leave/]);
 bcap('DAY 6: Sleep.');yield* bsleep();
 // DAY 7
 bcap('DAY 7: Harvest day. The turnips are ready.');yield* bmorning();yield* bgo('ranch');
 for(const k of Object.keys(FG.crop)){const[x,y]=k.split(',').map(Number);if(yield* bnear(x,y))yield* bpress()}
 bcap('DAY 7: Ship everything in the bin. The Shipper pays tomorrow.');yield* bobj('bin');yield* bmenu(/Ship everything/);yield* bdlg();
 bcap('DAY 7: Sleep. Week complete.');yield* bsleep();
 BOT.done=1;bcap('WEEK COMPLETE');fdlg(bsum(),()=>botStop())}
function btimeLeft(){if(BOT.done)return 'Done!';if(BOT.paused)return 'Paused';const r=Math.max(0,(BOT.total-BOT.n)/(BOT.speed*BOT.fps));if(BOT.n>=BOT.total)return 'Almost done';const m=Math.floor(r/60),s=Math.ceil(r%60);return 'Time left '+m+':'+String(s==60?59:s).padStart(2,'0')+' · Day '+Math.min(7,FG.day)+'/7'}
const SL={x:336,y:58,w:180,h:10};
function bslGet(){return Math.max(0,Math.min(1,Math.log(Math.max(.1,BOT.speed)/.1)/Math.log(120)))}
function bslSet2(v){BOT.speed=Math.round(Math.max(.1,Math.min(12,v))*100)/100;BOT.acc=0}
function bslT(x){return Math.max(0,Math.min(1,(x-SL.x)/SL.w))}
let botDrag=0;
function bpt(e){const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*640/r.width,y:(e.clientY-r.top)*448/r.height}}
try{cv.addEventListener('pointerdown',e=>{if(!BOT.on)return;const p=bpt(e);if(p.y>=SL.y-8&&p.y<=SL.y+SL.h+8&&p.x>=SL.x-8&&p.x<=SL.x+SL.w+8){botDrag=1;bslSet2(.1*Math.pow(120,bslT(p.x)));try{cv.setPointerCapture(e.pointerId)}catch(_){}e.preventDefault()}});
cv.addEventListener('pointermove',e=>{if(botDrag&&BOT.on)bslSet2(.1*Math.pow(120,bslT(bpt(e).x)))});
const bup=()=>{botDrag=0};cv.addEventListener('pointerup',bup);cv.addEventListener('pointercancel',bup)}catch(e){}
function botStart(){if(!(S&&S.char>=0))S.char=0;fgBegin();BOT.on=1;BOT.done=0;BOT.paused=0;BOT.speed=3;BOT.acc=0;BOT.n=0;BOT.lt=0;BOT.cap='';BOT.tacc=0;BOT.gen=bscript()}
function botStop(){BOT.on=0;BOT.gen=null;FG.ui=null;mode='start'}
function botStep(){BOT.n++;try{const r=BOT.gen.next();if(r.done&&!BOT.done){BOT.done=1}}catch(e){BOT.err=String(e&&e.stack||e);BOT.cap='Bot error: '+String(e&&e.message||e).slice(0,60);BOT.paused=1}}
const fgS0=fgSave;fgSave=function(){if(BOT.on)return;fgS0()};
const fgK0=fgKey;fgKey=function(k){if(BOT.on&&!BOT.int){
  if(BOT.done&&FG.ui&&FG.ui.t=='dlg')return fgK0(k);
  if(k=='Escape'){botStop();return}
  if(k==' '||k=='p'||k=='P'){BOT.paused=!BOT.paused;return}
  if(k=='1')bslSet2(.25);else if(k=='2')bslSet2(1);else if(k=='3')bslSet2(3);else if(k=='4')bslSet2(12);else if(k=='ArrowRight'||k=='+'||k=='=')bslSet2(BOT.speed*1.25);else if(k=='ArrowLeft'||k=='-')bslSet2(BOT.speed/1.25);return}
 fgK0(k)};
const fgC0=fgClick;fgClick=function(x,y){if(BOT.on&&!BOT.int){if(BOT.done&&FG.ui)return fgC0(x,y);if(y>=SL.y-8&&y<=SL.y+SL.h+8&&x>=SL.x-8&&x<=SL.x+SL.w+8)return;BOT.paused=!BOT.paused;return}fgC0(x,y)};
const fgF0=fgFrame;fgFrame=function(){{const nw=performance.now();if(BOT.lt&&nw>BOT.lt){const f=1000/(nw-BOT.lt);if(f>5&&f<200)BOT.fps=BOT.fps*.9+f*.1}BOT.lt=nw}if(BOT.on&&!BOT.paused&&BOT.gen&&!BOT.done){BOT.acc+=BOT.speed;let n=0;while(BOT.acc>=1&&n++<40){BOT.acc--;botStep();if(BOT.done)break}if(BOT.acc>4)BOT.acc=4}if(BOT.on)FG.acc=0;fgF0();if(BOT.on)FG.acc=0};
const fgD0=fgDraw;fgDraw=function(t){fgD0(t);if(!BOT.on)return;g.fillStyle='rgba(120,20,20,.9)';g.fillRect(0,40,640,16);txt('BOT SPEED RUN',8,52,10,'#fff');txt((BOT.cap||'').slice(0,64),112,52,10,'#ffe27a');txt(btimeLeft(),634,52,10,'#fff','right');g.fillStyle='#ffe27a';g.fillRect(0,69,640*Math.min(1,BOT.n/BOT.total),1);
 g.fillStyle='rgba(0,0,0,.7)';g.fillRect(0,56,640,14);txt('Space pause · Esc stop · Left/Right or drag the slider',6,67,9,'#cfc6a8');txt('SPEED',296,67,9,'#fff');g.fillStyle='#3a2a14';g.fillRect(SL.x,SL.y+3,SL.w,4);g.fillStyle='#e8c860';g.fillRect(SL.x,SL.y+3,SL.w*bslGet(),4);g.fillStyle='#fff';g.fillRect(SL.x+SL.w*bslGet()-3,SL.y,6,SL.h);txt(BOT.paused?'PAUSED':(BOT.speed<1?BOT.speed.toFixed(2):BOT.speed.toFixed(1)).replace(/[.]0$/,'')+'x',SL.x+SL.w+8,67,9,'#ffe27a')};

// ===== v8i: Farming & tool mechanics 2.0 =====
const TNAMES=['Basic','Copper','Silver','Gold'],TBADGE=['','Cu','Ag','Au'],TCOL=['#fff','#e0905a','#d8e0e8','#ffd84a'],TUP=[[400,5],[1000,10],[2500,20]],TOOLN=['Hoe','Watering Can','Sickle','Axe','Hammer'];
const MKC=['turnip','potato','tomato','corn','egg'],AREA={free:0};
INAME.sprinkler='Sprinkler';INAME.fert='Fertilizer';INAME.gro='Speed-Gro';IICO.sprinkler=20;IICO.fert=32;IICO.gro=12;
function tier(t){return(FG.tier&&FG.tier[t])|0}
function canCap(){return 20+10*tier(1)}
function fmkt(){const M={};let sd=FG.day*7919+11;const r=()=>(sd=(sd*16807)%2147483647)/2147483647;for(let i=0;i<5;i++)r();for(const k of MKC)M[k]=Math.round((.8+r()*.5)*100)/100;return M}
function ensureF(){if(!FG.on)return;FG.tier=FG.tier||[0,0,0,0,0];if(FG.can==null)FG.can=canCap();FG.fert=FG.fert||{};FG.spr=FG.spr||[];FG.q=FG.q||{};FG.mkt=FG.mkt||fmkt()}
// 1,2: tool tiers and stamina cost
