// 4,5: area effect and can charges
function areaTiles(tx,ty,t){const tr=tier(t);if(tr<2||t>2)return[[tx,ty]];if(tr==2){const px=FG.d%2==0?1:0,py=FG.d%2==0?0:1;return[[tx-px,ty-py],[tx,ty],[tx+px,ty+py]]}const o=[];for(let a=-1;a<=1;a++)for(let b=-1;b<=1;b++)o.push([tx+a,ty+b]);return o}
const ftool0=ftool;
function toolOne(x,y){const t=FG.tool,k=x+','+y,c=FG.crop[k];
 if(AREA.free&&!ffield(x,y))return;
 if(t==1&&FG.sc=='ranch'&&ffield(x,y)){if(!c){if(!AREA.free)fsay('Nothing to water.');return}if(c.w){if(!AREA.free)fsay('Already watered. No wasted stamina.');return}if(FG.can<=0){if(!AREA.free)fsay('The can is empty. Refill at the well or the mountain pond.');return}
  ftool0(x,y);if(c.w){FG.can--;}return}
 ftool0(x,y)}
ftool=function(tx,ty){ensureF();const t=FG.tool,T=areaTiles(tx,ty,t);toolOne(tx,ty);if(T.length>1){AREA.free=1;try{for(const[x,y]of T)if(x!=tx||y!=ty)toolOne(x,y)}finally{AREA.free=0}}}
// 7: smart tool
function fneed(tx,ty){const k=tx+','+ty,l=FG.land[k],c=FG.crop[k];if(FG.sc!='ranch'||!ffield(tx,ty))return -1;
 if(c){if(c.a>=CR[c.k].d)return -2;return(!c.w&&FG.can>0)?1:-1}
 if(l=='stump')return 3;if(l=='stone')return 4;if(l=='grass'||l=='weed')return 2;if(l=='soil')return 0;if(l=='till'&&(FG.seeds[SEEDS5[FG.seedSel]]|0)>0)return 8;return -1}
function fvalid(tx,ty){const n=fneed(tx,ty);if(n==-1&&!(FG.sc=='ranch'&&ffield(tx,ty)))return null;if(n==-2)return 1;return n==FG.tool?1:0}
