const TSTART=[{x:16,y:9,k:'oak',a:9,r:1,cd:0},{x:18,y:10,k:'maple',a:9,r:1,cd:0},{x:13,y:10,k:'cherry',a:9,r:0,cd:2}];
function ensureT(){if(FG.on&&!FG.trees)FG.trees=TSTART.map(t=>Object.assign({},t));FG.tsel=FG.tsel||'acorn'}
function treeAt(x,y){return FG.trees&&FG.sc=='ranch'?FG.trees.find(t=>t.x==x&&t.y==y):null}
function tstage(t){return t.a<3?0:t.a<7?1:2}
const fsT=fsolid;fsolid=function(x,y){if(FG.on&&!FG.trees)ensureT();if(FG.sc=='ranch'&&FG.trees&&FG.trees.some(t=>t.x==x&&t.y==y))return true;return fsT(x,y)};
const fgBT=fgBegin;fgBegin=function(){fgBT();ensureT()};
function tdoorFront(x,y){for(const o of OB.ranch)if(INT[o.id]){const a=doorA(o);if(y==o.y+o.h&&(x==a||x==a+1))return true}return false}
function tvalid(x,y){if(FG.sc!='ranch')return'Trees can only be planted on the ranch.';if(x<1||x>18||y<1||y>10)return'Too close to the edge of the ranch.';if(fsolid(x,y))return'Something is in the way.';if(ffield(x,y))return'The field is for crops. Plant trees outside the fenced plot.';if(FG.crop[x+','+y])return'There is a crop there.';if(tdoorFront(x,y))return'Do not block the door.';if(FG.trees.length>=30)return'The ranch is a forest already (30 trees max).';return''}
function tplant(){ensureT();const owned=TSEEDS.filter(k=>(FG.inv[k]|0)>0);if(!owned.length){fsay('No tree seeds. Shake trees for acorns and seeds, or buy an Acorn at Ned\'s.');return}
 if(!owned.includes(FG.tsel))FG.tsel=owned[0];const[tx,ty]=fgFace(),why=tvalid(tx,ty);if(why){fsay(why);return}
 const k=TKEYS[TSEEDS.indexOf(FG.tsel)];FG.inv[FG.tsel]--;FG.trees.push({x:tx,y:ty,k,a:0,r:0,cd:0});cn('tree_plant');fsay('Planted a '+TS[k].n+' sapling. Mature in 7 days (it rests in winter).')}
function tcycle(){ensureT();const owned=TSEEDS.filter(k=>(FG.inv[k]|0)>0);if(!owned.length){fsay('No tree seeds yet.');return}const i=owned.indexOf(FG.tsel);FG.tsel=owned[(i+1)%owned.length];fsay('Tree seed: '+INAME[FG.tsel]+' x'+FG.inv[FG.tsel])}
function tinfo(t){const T=TS[t.k],st=tstage(t);return T.n+' · '+['sapling','young','mature'][st]+' · '+(st<2?'mature in '+(7-t.a)+'d':t.r?T.s+' ready':T.s+' in '+Math.max(1,t.cd)+'d')}
function tshake(t){const T=TS[t.k];if(tstage(t)<2){fsay(tinfo(t)+'. Too small to shake.');return}if(!t.r){fsay('Nothing falls. '+tinfo(t)+'.');return}
 let n=t.k=='willow'?1:1+Math.floor(Math.random()*3);if(fseason()==2&&t.k!='willow')n++;FG.inv[T.seed]=(FG.inv[T.seed]|0)+n;t.r=0;t.cd=T.base;cn('tree_shake');cn('tree_seed',n);fsay('You shook the '+T.n+': '+n+' '+(n>1?T.s:T.s.replace(/s$/,''))+' fell!')}
function tchop(t){const T=TS[t.k],st=tstage(t);if(!fuse(st==0?1:6))return;FG.trees.splice(FG.trees.indexOf(t),1);
 const w=st==0?0:st==1?2:T.wood;FG.inv.wood=(FG.inv.wood|0)+w;cn('tree_chop');
 if(st==2&&Math.random()<.5){FG.inv[T.seed]=(FG.inv[T.seed]|0)+1;fsay('Chopped a '+T.n+': Wood +'+w+' and a '+T.s.replace(/s$/,'')+' rolled out.')}else fsay(st==0?'You uprooted a sapling.':'Chopped a '+T.n+': Wood +'+w+'.')}
const factT=fact;fact=function(){if(FG.ui||FG.sc!='ranch')return factT();ensureT();const[tx,ty]=fgFace(),t=treeAt(tx,ty);if(t){if(FG.tool==3)tchop(t);else tshake(t);return}factT()};
const fndT=fnewday;fnewday=function(pass){fndT(pass);ensureT();const s=fseason();for(const t of FG.trees){if(s==3)continue;t.a++;if(t.a==7){t.r=1;t.cd=0}if(t.a>7&&!t.r){t.cd-=(s==2?2:1);if(t.cd<=0){t.r=1;t.cd=0}}}};
const fgKT=fgKey;fgKey=function(k){if(FG.on&&!BOT.on&&!FG.ui&&FG.sc=='ranch'&&!UIX.panel&&!UIX.paused){if(k=='g'||k=='G'){tplant();return}if(k=='b'||k=='B'){tcycle();return}}fgKT(k)};
const ftnT=ftargetName;ftargetName=function(){if(!FG.ui&&FG.sc=='ranch'&&FG.trees){const[tx,ty]=fgFace(),t=treeAt(tx,ty);if(t){const T=TS[t.k];return FG.tool==3?'E: Chop the '+T.n:(tstage(t)==2&&t.r)?'E: Shake the '+T.n+' ('+T.s+')':'E: Inspect the '+T.n}}return ftnT()};
