let TM={};
const gtT=gtile;gtile=function(sc,x,y,t){gtT(sc,x,y,t);if(sc!='ranch')return;const tr=TM[x+','+y];if(!tr)return;const st=tstage(tr),sw=st==2?Math.sin(t*1.5+x)*.8:0;
 g.fillStyle='rgba(0,0,0,.25)';g.fillRect(x*32+6,y*32+26,20,5);spr('ftree_'+tr.k+'_'+st,x*32-12+sw,y*32-22,56);
 if(st==2&&tr.r&&Math.floor(t*3+x)%2){g.fillStyle=TS[tr.k].col;g.fillRect(x*32+8,y*32-8,3,3);g.fillRect(x*32+20,y*32-4,3,3);g.fillRect(x*32+14,y*32,3,3);g.fillStyle='#fff';g.fillRect(x*32+9,y*32-7,1,1)}};
const fgDT=fgDraw;fgDraw=function(t){if(FG.on)ensureT();TM={};if(FG.on&&FG.trees)for(const tr of FG.trees)TM[tr.x+','+tr.y]=tr;fgDT(t);
 if(!FG.on||(FG.ui&&FG.ui.t=='end')||FG.sc!='ranch'||!FG.trees)return;
 if(!FG.ui){const[tx,ty]=fgFace(),tr=treeAt(tx,ty);if(tr){const s=tinfo(tr),w=s.length*5.4+8,bx=Math.max(2,Math.min(638-w,tx*32+16-w/2)),by=Math.max(44,ty*32-26);g.fillStyle='rgba(0,0,0,.78)';g.fillRect(bx,by,w,13);g.strokeStyle='#9ee08a';g.strokeRect(bx+.5,by+.5,w-1,12);txt(s,bx+4,by+10,9,'#fff')}
  const owned=TSEEDS.filter(k=>(FG.inv[k]|0)>0);if(owned.length){const sel=owned.includes(FG.tsel)?FG.tsel:owned[0],s='G: plant '+INAME[sel]+' x'+FG.inv[sel]+(owned.length>1?' · B: change':''),w=s.length*5+10;g.fillStyle='rgba(0,0,0,.75)';g.fillRect(634-w,402,w,12);txt(s,634-5,411,8,'#9ee08a','right')}
  if(0){for(const tr of FG.trees){g.fillStyle=tstage(tr)==2?'#3f9a3a':'#8fd070';g.fillRect(574+tr.x*3,372+tr.y*3,2,2)}}}};
