function ash(c,f){const n=parseInt(c.slice(1),16);let r=n>>16,gg=n>>8&255,bb=n&255;const m=f<0?0:255,k=Math.abs(f);r=Math.round(r+(m-r)*k);gg=Math.round(gg+(m-gg)*k);bb=Math.round(bb+(m-bb)*k);return'#'+((1<<24)|(r<<16)|(gg<<8)|bb).toString(16).slice(1)}
function alum(c){const n=parseInt(c.slice(1),16);return((n>>16)*299+(n>>8&255)*587+(n&255)*114)/1000}
