// ===== v8p: 50 gameplay improvements =====
function jl(k,s){if(typeof jlog=='function')jlog(k,s)}
const GBASE={flower:10,fish:15,cake:25,mush:12,herb:12,grapes:12,fruit:14,egg:8,milkS:10,milkM:14,milkL:18,turnip:8,potato:8,tomato:9,corn:10,stew:22,bread:20,soup:21};
Object.assign(INAME,{stew:'Veg Stew',bread:'Corn Bread',soup:'Tomato Soup'});Object.assign(PRICE,{stew:300,bread:250,soup:280});
const BD=[[0,8],[1,14],[2,5],[3,17],[1,27]];
const GT=[{l:['herb','grapes','stew'],k:['flower','cake','potato','soup'],h:['fish','pmush']},{l:['milkL','egg','cake'],k:['corn','potato','milkM','bread'],h:['herb','pmush']},{l:['flower','fruit'],k:['grapes','cake','tomato','soup'],h:['fish','mush']},{l:['fish','mush'],k:['turnip','cake','corn','bread'],h:['flower']},{l:['grapes','cake','tomato'],k:['fish','herb','stew'],h:['turnip','egg']}];
const HEVT=[[['Marlowe: I saved you a seat in the Library. It has the good cushion.','Marlowe: Do not tell anyone about the cushion. (She slides you 100g. "Research stipend.")'],['Marlowe: I found your ranch in a book. Chapter 4: "Ground". It was not flattering.','Marlowe: So I wrote you a better chapter. (She hands you a Cave Herb.)'],['Marlowe: I would like to read the same book as you. For a long time. The book is long.','(She gives you 300g and a Cake. Both are very symbolic.)']],
[['Annika: Your cow is jealous of my cow. Neither will admit it.','(She gives you 100g for "cow diplomacy".)'],['Annika: Come to the barn at dawn. The cows hum. It is not a metaphor.','(She gives you a Large Milk.)'],['Annika: If I ever leave the ranch, I want it to be for yours.','(She gives you 300g and a Cake.)']],
[['Nadia: I made you a bouquet. It is a threat. It says: be nice to flowers.','(You get 100g and a mild sense of danger.)'],['Nadia: Flowers are just plants that learned to market themselves. Like you.','(She hands you a Flower.)'],['Nadia: The whole shop smells like you now. I am not mad.','(She gives you 300g and a Cake.)']],
[['Ellery: Koro misses you. I do not. Okay. I do.','(He gives you 100g he found in a coat.)'],['Ellery: Let us fish. Silently. Whoever speaks first buys lunch.','(He hands you a Fish.)'],['Ellery: I would like to stay. In the town. Near your dog.','(He gives you 300g and a Cake.)']],
[['Evie: First drink is on me. Second is also on me. I lose money on you.','(She slides you 100g.)'],['Evie: You are the only customer who tips in turnips. I respect that.','(She hands you Wild Grapes.)'],['Evie: Stay for last call. Stay for the one after it.','(She gives you 300g and a Cake.)']]];
const COWN=['Bessie','Daisy','Clover','Mabel','Petunia','Gertie','Buttercup','Moo-ana'];
const HREW=[['herb'],['milkL'],['flower'],['fish'],['grapes']];
function ensureP(){if(!FG.on||FG.p8)return;FG.p8=1;const d=FG.day;FG.bk=FG.bk|0;FG.ln=FG.ln||null;FG.gl=FG.gl||[0,0,0,0,0];FG.hev=FG.hev||[0,0,0,0,0];FG.lt=FG.lt||[d,d,d,d,d];FG.nw=FG.nw||[0,0,0,0,0];FG.t2=FG.t2||[0,0,0,0,0];FG.tc=FG.tc|0;FG.req=FG.req||null;FG.luck=FG.luck|0;FG.scare=FG.scare|0;FG.silo=FG.silo|0;FG.coupon=FG.coupon|0;FG.sb=FG.sb|0;FG.shv=FG.shv|0;FG.pp=FG.pp|0;FG.ms=FG.ms|0;FG.dif=FG.dif===undefined?1:FG.dif;FG.ach=FG.ach||{};FG.cs=FG.cs|0;FG.pet=FG.pet|0;FG.rest=FG.rest||[0,0];FG.mb=FG.mb|0;FG.buff=FG.buff||null;FG.fs=FG.fs|0;FG.wk=FG.wk||{g:FG.gold,d:FG.day};FG.shs=FG.shs|0;FG.soak=FG.soak|0;FG.xegg=FG.xegg|0}
const fgBP=fgBegin;fgBegin=function(){fgBP();ensureP()};
const NUL=0;
function isBD(i){return fseason()==BD[i][0]&&dom(FG.day)==BD[i][1]}
function hearts(i){return Math.floor(FG.aff[i]/40)}
function lvlOf(x){const T=[20,60,150,300,600];let l=0;for(const t of T)if(x>=t)l++;return l}
function xpFarm(){let s=0;const c=FG.cnt||{};for(const k in c)if(/^(till|water|plant_|harv_|ship_)/.test(k))s+=c[k];return s}
function xpRanch(){const c=FG.cnt||{};return(c.brush|0)+(c.milk|0)+((FG.st2&&FG.st2.eggs)|0)}
function xpSocial(){const c=FG.cnt||{};return(FG.tc|0)+(c.gift|0)*2}
function skillLv(){return{farm:lvlOf(xpFarm()),ranch:lvlOf(xpRanch()),social:lvlOf(xpSocial())}}
const TITLES=['Newcomer','Sprout','Farmhand','Farmer','Rancher','Landowner','Local Legend'];
function ftitle(){ensureP();const s=skillLv(),p=s.farm+s.ranch+s.social+(FG.house|0)+Math.floor((FG.shv|0)/3000);return TITLES[Math.max(0,Math.min(6,Math.floor(p/2.5)))]}
function nextFest(){for(let o=0;o<=120;o++){const dd=FG.day+o,s=Math.floor(((dd-1)%120)/30),d=((dd-1)%30)+1,f=FEST[s+','+d];if(f&&!(f=='newyear'&&yr(dd)==1))return{f,o,name:FESTN[f]}}return null}
// ---- G1-G10 social
const GIFTK=Object.keys(GBASE);
function gtaste(i,k){const t=GT[i];return t.l.includes(k)?2.5:t.k.includes(k)?1.5:t.h.includes(k)?-.6:1}
function gdelta(i,k){return Math.round(GBASE[k]*gtaste(i,k)*(isBD(i)?3:1))}
fgift=function(i){ensureP();const g_=GIRLS[i],o=[];
 if(FG.gl[i]==FG.day){fsay(g_.n+': One gift a day is plenty. I have a reputation for not being greedy.');return}
 for(const k of GIFTK)if((FG.inv[k]||0)>0){const t=gtaste(i,k),tag=t>=2.5?' ♥ loves':t>=1.5?' likes':t<0?' ✗ hates':'';o.push({t:INAME[k]+' x'+FG.inv[k]+' ('+(gdelta(i,k)>=0?'+':'')+gdelta(i,k)+tag+')',go:()=>{const dlt=gdelta(i,k);FG.inv[k]--;FG.aff[i]=Math.max(0,Math.min(255,FG.aff[i]+dlt));FG.gl[i]=FG.day;FG.lt[i]=FG.day;cn('gift');fclose();const tt=gtaste(i,k);fsay(g_.n+(tt>=2.5?' LOVED the ':tt>=1.5?' liked the ':tt<0?' hated the ':' accepted the ')+INAME[k]+(isBD(i)?' (birthday x3!)':'')+'. ('+(dlt>=0?'+':'')+dlt+')');jl('gift','Gave '+INAME[k]+' to '+g_.n+' ('+(dlt>=0?'+':'')+dlt+' affection)')}})}
 if((FG.inv.feather||0)>0&&FG.married<0)o.push({t:'Blue Feather (proposal!)',go:()=>fprop(i)});
 if(!o.length)o.push({t:'(nothing to give. Perfume is not an option.)',go:fclose});o.push({t:'Back',go:()=>ftalk(i)});fmenu('Gift for '+g_.n+(isBD(i)?' — BIRTHDAY x3':''),o)};
function heartEvent(i,lvl){const g_=GIRLS[i],L=HEVT[i][lvl-1].slice(),k=HREW[i][0];
 if(lvl==1)FG.gold+=100;else if(lvl==2)FG.inv[k]=(FG.inv[k]||0)+1;else{FG.gold+=300;FG.inv.cake=(FG.inv.cake||0)+1}
 FG.aff[i]=Math.min(255,FG.aff[i]+2);cn('heartev');jl('heart','Heart event '+lvl+'/3 with '+g_.n);fdlg(['HEART EVENT: '+g_.n+' ('+lvl+'/3)'].concat(L))}
function newsFor(i){const nf=nextFest(),fc={sun:'sunny',rain:'rainy',snow:'snowy',storm:'a HURRICANE'}[FG.fcast]||'fine',M=fmkt();let best='turnip',bv=0;for(const k in M)if(M[k]>bv){bv=M[k];best=k}
 const P=[['Tomorrow looks '+fc+'. '+(FG.fcast=='storm'?'Bring in the animals.':'Plan accordingly.')],[nf?nf.name+' is '+(nf.o?'in '+nf.o+' days.':'TODAY.'):'No festivals left on the calendar.'],['Prices: '+(INAME[best]||best)+' is selling at x'+bv.toFixed(2)+' today.'],['Luck today: '+(FG.luck>0?'good':FG.luck<0?'bad':'average')+'.']];
 return GIRLS[i].n+': '+P[(FG.day+i)%P.length][0]}
ftalk=function(i){ensureP();const g_=GIRLS[i],a=FG.aff[i],tier=a<80?0:a<160?1:2,ls=FTALK[i][tier];FG.met=FG.met||{};FG.met[i]=1;
 const hv=hearts(i)>=6?3:hearts(i)>=4?2:hearts(i)>=2?1:0;if(hv>(FG.hev[i]|0)){FG.hev[i]=(FG.hev[i]|0)+1;heartEvent(i,FG.hev[i]);return}
 const opts=[{t:'Chat'+(FG.talked[i]?' (again, +1)':''),go:()=>{fclose();const l=ls[(FG.day+i)%ls.length];FG.tc++;FG.lt[i]=FG.day;cn('talk');
  fdlg([l],()=>{if(!FG.talked[i]){FG.talked[i]=1;const add=4+(skillLv().social>>1)+(isBD(i)?2:0);FG.aff[i]=Math.min(255,FG.aff[i]+add);fsay(g_.n+' likes that. (+'+add+')')}else if(FG.t2[i]!=FG.day){FG.t2[i]=FG.day;FG.aff[i]=Math.min(255,FG.aff[i]+1);fsay(g_.n+' smiles again. (+1)')}})}},
  {t:'Give a gift'+(FG.gl[i]==FG.day?' (given today)':''),go:()=>fgift(i)}];
 if(hearts(i)>=1&&FG.nw[i]!=FG.day)opts.push({t:'Ask for news',go:()=>{fclose();FG.nw[i]=FG.day;cn('news');fdlg([newsFor(i)])}});
 if(FG.married==i&&FG.left)opts.unshift({t:'Apologize',go:()=>{fclose();FG.left=0;FG.aff[i]=Math.max(FG.aff[i],140);fdlg([g_.n+': Fine. I am coming home. Bring cake next time.'])}});
 opts.push({t:'Leave',go:fclose});fmenu(g_.n+'  ('+hearts(i)+' hearts)'+(isBD(i)?'  ♥ BIRTHDAY':''),opts)};
const fcalP=fcal;fcal=function(){fcalP();if(FG.ui&&FG.ui.l){FG.ui.l.push('Birthdays: '+GIRLS.map((g_,i)=>g_.n+' '+SEAS4[BD[i][0]].slice(0,3)+' '+BD[i][1]).join(', '));FG.ui.l.push('Luck today: '+(FG.luck>0?'+':'')+FG.luck+'. Title: '+ftitle()+'.')}};
// ---- G11 pet, G44 rest, G49 chores
function petDog(){ensureP();if(!FG.flags.dog){fsay('You have no dog yet. Ellery shows up on Day 2.');return}if(FG.pet==FG.day){fsay('Koro is asleep. He has been petted. He is complete.');return}FG.pet=FG.day;FG.st=Math.min(FG.mst,FG.st+8);cn('pet');fsay('You pet Koro. +8 stamina. He does not know why either.')}
function restHour(){ensureP();if(FG.rest[0]!=FG.day)FG.rest=[FG.day,0];if(FG.rest[1]>=3){fsay('You have rested enough today. The ranch is judging you.');return}if(FG.min>=1260){fsay('Too late to rest. Go to bed.');return}FG.rest[1]++;FG.min=Math.min(1380,FG.min+60);FG.st=Math.min(FG.mst,FG.st+10);cn('rest');fsay('You rest for an hour. +10 stamina. ('+FG.rest[1]+'/3 today)')}
function quickChores(){ensureP();if(FG.sc!='ranch'){fsay('Quick chores only work on the ranch.');return}if(!FG.cows.length&&!FG.hens.length){fsay('No animals to feed.');return}if(!fuse(2))return;let n=0;for(const c of FG.cows)if(!c.fed&&(FG.inv.fodder||0)>0){c.fed=1;FG.inv.fodder--;n++}for(const h of FG.hens)if(!h.fed&&(FG.inv.fodder||0)>0){h.fed=1;FG.inv.fodder--;n++}cn('quickfeed');fsay(n?'Quick chores: fed '+n+' animals.':'Everyone is already fed (or you are out of fodder).')}
const fgKP=fgKey;fgKey=function(k){if(FG.on&&!BOT.on&&!FG.ui&&!UIX.panel&&!UIX.paused){if(k=='y'||k=='Y'){petDog();return}if(k=='z'||k=='Z'){restHour();return}if(k=='c'||k=='C'){quickChores();return}}fgKP(k)};
