 for(const k in FG.cnt){const d=FG.cnt[k]-(FG.jc[k]|0);if(d>0){const w=FG.jw[FG.day]||(FG.jw[FG.day]={});w[k]=(w[k]|0)+d;if(/^fest_/.test(k)&&FESTN[k.slice(5)])jlog('event','Attended: '+FESTN[k.slice(5)])}FG.jc[k]=FG.cnt[k]}
