 if((uc||uh)&&(FG.inv.fodder|0)>0)L.push('Feed '+(uc+uh)+' animals ('+(FG.inv.fodder|0)+' fodder). Press C on the ranch for quick chores.');
 else if((uc||uh))L.push('Animals need fodder: cut grass with the sickle or buy some at Hugh\'s.');
 const ml=cows.filter(c=>c.milk).length,eg=hens.filter(h=>h.egg).length;if(ml)L.push('Milk '+ml+' cow'+(ml>1?'s':'')+' in the barn.');if(eg)L.push('Collect '+eg+' egg'+(eg>1?'s':'')+' from the coop.');
