function mzrng(s){return()=>(s=(s*16807)%2147483647)/2147483647}
function mzSize(i){return[9+Math.floor(i*.54),7+Math.floor(i*.34)]}
function mzGen(i){const[cols,rows]=mzSize(i),r=mzrng(i*104729+977),w=new Uint8Array(cols*rows).fill(15),B=[1,2,4,8],DX=[0,1,0,-1],DY=[-1,0,1,0],OP=[4,8,1,2],seen=new Uint8Array(cols*rows),st=[[0,0]];seen[0]=1;
 while(st.length){const[x,y]=st[st.length-1],nb=[];for(let d=0;d<4;d++){const nx=x+DX[d],ny=y+DY[d];if(nx>=0&&ny>=0&&nx<cols&&ny<rows&&!seen[ny*cols+nx])nb.push(d)}
  if(!nb.length){st.pop();continue}const d=nb[Math.floor(r()*nb.length)],nx=x+DX[d],ny=y+DY[d];w[y*cols+x]&=~B[d];w[ny*cols+nx]&=~OP[d];seen[ny*cols+nx]=1;st.push([nx,ny])}
 const br=i<15?0:Math.min(.4,(i-14)*.012);if(br>0)for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const c=w[y*cols+x];let o=0;for(let d=0;d<4;d++)if(!(c&B[d]))o++;if(o==1&&r()<br){const ds=[0,1,2,3].filter(d=>{const nx=x+DX[d],ny=y+DY[d];return(c&B[d])&&nx>=0&&ny>=0&&nx<cols&&ny<rows});if(ds.length){const d=ds[Math.floor(r()*ds.length)];w[y*cols+x]&=~B[d];w[(y+DY[d])*cols+x+DX[d]]&=~OP[d]}}}
 const k=i%4,sx=(k==0||k==1)?0:cols-1,sy=(k==0||k==3)?0:rows-1,gx=cols-1-sx,gy=rows-1-sy;
 const M={i,cols,rows,w,sx,sy,gx,gy,t:MZT[i]};const D=mzDist(M,sx,sy);M.dist=D;M.len=D[gy*cols+gx];M.par=Math.round(M.len*.32+6);
 const ends=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const c=w[y*cols+x];let o=0;for(let d=0;d<4;d++)if(!(c&B[d]))o++;if(o==1&&!(x==sx&&y==sy)&&!(x==gx&&y==gy))ends.push([D[y*cols+x],x,y])}
 let pool=ends.length>=3?ends:[];if(pool.length<3){pool=[];for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)if(!(x==sx&&y==sy)&&!(x==gx&&y==gy))pool.push([D[y*cols+x],x,y])}
 pool.sort((a,b)=>a[0]-b[0]);M.gems=[.2,.5,.85].map(q=>{const p=pool[Math.min(pool.length-1,Math.floor(q*pool.length))];return{x:p[1],y:p[2],got:0}});
 const seenG={};M.gems.forEach((g0,j)=>{let key=g0.x+','+g0.y,n=0;while(seenG[key]&&n<pool.length){const p=pool[(j*7+n+1)%pool.length];g0.x=p[1];g0.y=p[2];key=g0.x+','+g0.y;n++}seenG[key]=1});return M}
function mzDist(M,sx,sy){const{cols,rows,w}=M,D=new Int32Array(cols*rows).fill(-1),q=[[sx,sy]];D[sy*cols+sx]=0;const B=[1,2,4,8],DX=[0,1,0,-1],DY=[-1,0,1,0];
 for(let h=0;h<q.length;h++){const[x,y]=q[h];for(let d=0;d<4;d++){if(w[y*cols+x]&B[d])continue;const nx=x+DX[d],ny=y+DY[d];if(nx<0||ny<0||nx>=cols||ny>=rows||D[ny*cols+nx]>=0)continue;D[ny*cols+nx]=D[y*cols+x]+1;q.push([nx,ny])}}return D}
function mzPath(M,fx,fy,tx,ty){const{cols,rows,w}=M,B=[1,2,4,8],DX=[0,1,0,-1],DY=[-1,0,1,0],prev=new Int32Array(cols*rows).fill(-2),q=[[fx,fy]];prev[fy*cols+fx]=-1;
 for(let h=0;h<q.length;h++){const[x,y]=q[h];if(x==tx&&y==ty)break;for(let d=0;d<4;d++){if(w[y*cols+x]&B[d])continue;const nx=x+DX[d],ny=y+DY[d];if(nx<0||ny<0||nx>=cols||ny>=rows||prev[ny*cols+nx]!=-2)continue;prev[ny*cols+nx]=y*cols+x;q.push([nx,ny])}}
 const p=[];let c=ty*cols+tx;if(prev[c]==-2)return p;while(c!=-1&&c!=fy*cols+fx){p.unshift([c%cols,c/cols|0]);c=prev[c]}return p}
