function mzBuild(){const M=MZ.M,T=M.t,cs=MZ.cs,c=document.createElement('canvas');c.width=M.cols*cs*2;c.height=M.rows*cs*2;const q=c.getContext('2d');q.imageSmoothingEnabled=false;q.scale(2,2);const r=mzrng(M.i*31+5),sh=MZSH[T[6]],ps=Math.max(1,Math.floor(cs/12));
 for(let y=0;y<M.rows;y++)for(let x=0;x<M.cols;x++){q.fillStyle=(x+y)%2?T[3]:T[2];q.fillRect(x*cs,y*cs,cs,cs);
  if(r()<.34&&cs>=12){q.globalAlpha=.3;q.fillStyle=T[5];const ox=x*cs+Math.floor((cs-7*ps)*r()),oy=y*cs+Math.floor((cs-7*ps)*r());sh.forEach((row,j)=>{for(let k=0;k<7;k++)if(row[k]!='.')q.fillRect(ox+k*ps,oy+j*ps,ps,ps)});q.globalAlpha=1}}
 const lw=Math.max(2,Math.round(cs*.16)),h=lw/2,w=M.w;
 for(let y=0;y<M.rows;y++)for(let x=0;x<M.cols;x++){const v=w[y*M.cols+x],X=x*cs,Y=y*cs;q.fillStyle=T[4];if(v&1)q.fillRect(X-h,Y-h,cs+lw,lw);if(v&2)q.fillRect(X+cs-h,Y-h,lw,cs+lw);if(v&4)q.fillRect(X-h,Y+cs-h,cs+lw,lw);if(v&8)q.fillRect(X-h,Y-h,lw,cs+lw)}
 q.globalAlpha=.4;q.fillStyle='#fff';for(let y=0;y<M.rows;y++)for(let x=0;x<M.cols;x++){const v=w[y*M.cols+x],X=x*cs,Y=y*cs;if(v&1)q.fillRect(X-h,Y-h,cs+lw,1);if(v&8)q.fillRect(X-h,Y-h,1,cs+lw)}q.globalAlpha=1;MZ.cache=c}
