function fishAvail(){fishInit();const wet=FG.weather=='rain'||FG.weather=='storm',lk=1+.15*(FG.luck|0)+.08*fishLv();return FSP.map(f=>{let w=0;if((f.s>>fseason())&1&&fishHour(f)&&(f.wx=='any'||(f.wx=='wet')==wet)){w=f.w;if(!f.junk&&f.d>=4)w*=Math.max(.3,lk);if(f.id=='trout'&&wet)w*=2;if(f.junk)w=f.w*(1-.1*fishLv())}return[f,w]}).filter(a=>a[1]>0)}
