function fishEnd(){FSH.on=0;if(FG.ui&&FG.ui.t=='fishing')FG.ui=null}
function fishHook(){const f=FSH.sp;if(f.junk){fishCatch();return}const lv=fishLv();FSH.ph='reel';FSH.p=.5;FSH.tg=Math.random();FSH.tt=.6;FSH.z=.5;FSH.vz=0;FSH.pr=.3;FSH.zw=Math.max(.14,.34+.03*lv-.04*(f.d-1));FSH.el=0}
