 FG.cnt.fish=(FG.cnt.fish|0)+1;const big=!f.junk&&sz>=f.a+(f.b-f.a)*.85;
 fsay((f.junk?'You reeled in: ':'Caught: ')+f.n+' ('+sz+' cm, '+f.p+'g)'+(big?' HUGE!':'')+(isNew&&!f.junk?' NEW!':''));jl('event',(f.junk?'Fished up ':'Caught a ')+f.n+' ('+sz+' cm)'+(isNew&&!f.junk?' - new in the Fish Log':''));
