function fishLose(why){fsay(why);fishEnd()}
function fishTick(){if(!FSH.on)return;const now=performance.now(),dt=Math.min(.05,(now-FSH.last)/1000);FSH.last=now;FSH.rip+=dt;
 if(FSH.ph=='wait'){FSH.t-=dt;if(FSH.t<=0){FSH.ph='bite';FSH.t=1.0+fishLv()*.12}}
 else if(FSH.ph=='bite'){FSH.t-=dt;if(FSH.t<=0)fishLose('Too slow. It got away.')}
 else if(FSH.ph=='reel'){const f=FSH.sp,hold=(typeof keys!='undefined'&&(keys.e||keys.E||keys[' ']))||FSH.mouse;FSH.el+=dt;
  FSH.tt-=dt;if(FSH.tt<=0||Math.abs(FSH.tg-FSH.p)<.02){FSH.tg=Math.random();FSH.tt=.5+Math.random()*.9}
  const sp=.22+.1*f.d,df=FSH.tg-FSH.p;FSH.p+=Math.sign(df)*Math.min(Math.abs(df),sp*dt);
  FSH.vz=Math.max(-.9,Math.min(.9,FSH.vz+(hold?1.9:-1.6)*dt));FSH.z+=FSH.vz*dt;if(FSH.z<0){FSH.z=0;FSH.vz=0}if(FSH.z>1){FSH.z=1;FSH.vz=0}
  const ov=Math.abs(FSH.p-FSH.z)<=FSH.zw/2;FSH.ov=ov;FSH.pr+=ov?(.3+.03*fishLv())*dt:-(.2+.03*f.d)*dt;
  if(FSH.pr>=1)fishCatch();else if(FSH.pr<=0)fishLose('The line went slack. It got away.')}}
