 g.fillStyle='#10202c';g.fillRect(X+44,Y,12,H);g.fillStyle=FSH.pr>.7?'#6aff8a':FSH.pr>.35?'#ffd84a':'#ff6a4a';const ph2=H*Math.max(0,Math.min(1,FSH.pr));g.fillRect(X+44,Y+H-ph2,12,ph2);
