// forage spawning
function wPickF(){const s=fseason(),P=WFZ.filter(f=>!f[3].length||f[3].includes(s));return P[Math.floor(Math.random()*P.length)][0]}
function wSpawn(){let sd=FG.day*7331+19;const r=()=>(sd=(sd*16807)%2147483647)/2147483647;for(let i=0;i<4;i++)r();FG.fz=[];const s=fseason(),P=WFZ.filter(f=>!f[3].length||f[3].includes(s));
 const plan=[['mtn',5],['ranch',3],['town',2]];for(const[sc,n]of plan){let placed=0,tries=0;while(placed<n&&tries++<80){const x=1+(r()*18|0),y=1+(r()*9|0);const keep=FG.sc;FG.sc=sc;const ok=wFreeTile(x,y);FG.sc=keep;if(!ok)continue;if(sc=='mtn'&&FG.mtn&&FG.mtn.some(m=>m.x==x&&m.y==y))continue;FG.fz.push({sc,x,y,k:P[Math.floor(r()*P.length)][0]});placed++}}
 let t=0;while(t++<30){const x=1+(r()*18|0),y=1+(r()*9|0),keep=FG.sc;FG.sc='mtn';const ok=wFreeTile(x,y);FG.sc=keep;if(ok){FG.fz.push({sc:'mtn',x,y,k:'rock'});if(FG.fz.filter(f=>f.k=='rock').length>=3)break}}}
function wDrawFz(sc,x,y){if(!FG.fz)return;for(const f of FG.fz){if(f.sc!=sc||f.x!=x||f.y!=y)continue;const X=x*32,Y=y*32;if(f.k=='rock'){g.fillStyle='rgba(0,0,0,.25)';g.fillRect(X+5,Y+24,22,5);g.fillStyle='#7a7e88';g.fillRect(X+5,Y+12,22,14);g.fillStyle='#9a9ea8';g.fillRect(X+8,Y+8,16,6);g.fillStyle='#5a5e68';g.fillRect(X+5,Y+22,22,4)}else{g.fillStyle='rgba(0,0,0,.22)';g.fillRect(X+8,Y+25,16,4);wico(f.k,X+4,Y+2+Math.sin((tclock||0)*2+x)*1.5,24)}}}
function wPickFz(tx,ty){if(!FG.fz)return false;const i=FG.fz.findIndex(f=>f.sc==FG.sc&&f.x==tx&&f.y==ty&&f.k!='rock');if(i<0)return false;const f=FG.fz[i];FG.fz.splice(i,1);const dbl=FG.tool>=10&&WTOOLS[FG.tool-10]&&WTOOLS[FG.tool-10][0]=='basket'&&wToolOwned(FG.tool-10);const n=dbl?2:1;FG.inv[f.k]=(FG.inv[f.k]|0)+n;FG.st2&&(FG.st2.forage=(FG.st2.forage|0)+n);FG.fgc=(FG.fgc|0)+n;cn('forage',n);fsay('Foraged: '+INAME[f.k]+(dbl?' x2 (basket!)':''));return true}

