 if(MS.m=='sel'){let s=MS.sel;if(k=='ArrowRight'||k=='d')s=Math.min(49,s+1);else if(k=='ArrowLeft'||k=='a')s=Math.max(0,s-1);else if(k=='ArrowDown'||k=='s')s=Math.min(49,s+10);else if(k=='ArrowUp'||k=='w')s=Math.max(0,s-10);else if(k=='Escape'){msmOpen();return}else if(k=='Enter'||k==' '||k=='e'){if(s+1<=P.unl)msStart(s+1);else msSay('Locked');return}MS.sel=s;return}
