// ===== v8y part 1: audio - sound effects + procedural soundtrack =====
const AUD={ctx:null,mg:null,sg:null,m:1,s:1,track:'',step:0,next:0,seed:7,tm:null,okU:0};
try{const q=JSON.parse(localStorage.getItem('lwaud')||'null');if(q){AUD.m=q.m?1:0;AUD.s=q.s?1:0}}catch(e){}
function audSave(){try{localStorage.setItem('lwaud',JSON.stringify({m:AUD.m,s:AUD.s}))}catch(e){}}
function audR(){AUD.seed=(AUD.seed*1664525+1013904223)>>>0;return AUD.seed/4294967296}
function audInit(){if(AUD.ctx||typeof AudioContext=='undefined'&&typeof webkitAudioContext=='undefined')return;try{const C=window.AudioContext||window.webkitAudioContext;const c=new C();AUD.ctx=c;AUD.mg=c.createGain();AUD.sg=c.createGain();const mst=c.createGain();mst.gain.value=.8;const cmp=c.createDynamicsCompressor?c.createDynamicsCompressor():null;AUD.mg.connect(mst);AUD.sg.connect(mst);if(cmp){mst.connect(cmp);cmp.connect(c.destination)}else mst.connect(c.destination);audVol();const nb=c.createBuffer(1,c.sampleRate,c.sampleRate),d=nb.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=audR()*2-1;AUD.nb=nb;AUD.next=c.currentTime+.1;if(!AUD.tm)AUD.tm=setInterval(audSched,90)}catch(e){AUD.ctx=null}}
function audVol(){if(!AUD.ctx)return;AUD.mg.gain.value=AUD.m?.2:0;AUD.sg.gain.value=AUD.s?.55:0}
function audResume(){audInit();try{if(AUD.ctx&&AUD.ctx.state!='running')AUD.ctx.resume()}catch(e){}}
const audMidi=n=>440*Math.pow(2,(n-69)/12);
function audTone(f,t,d,type,vol,dest,f2,att){const c=AUD.ctx,o=c.createOscillator(),g=c.createGain();o.type=type||'sine';o.frequency.setValueAtTime(f,t);if(f2)o.frequency.exponentialRampToValueAtTime(Math.max(20,f2),t+d);const a=att||.008;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vol,t+a);g.gain.exponentialRampToValueAtTime(.0004,t+d);o.connect(g);g.connect(dest);o.start(t);o.stop(t+d+.05)}
function audNoise(t,d,vol,dest,hp){const c=AUD.ctx,s=c.createBufferSource(),g=c.createGain(),f=c.createBiquadFilter();s.buffer=AUD.nb;f.type=hp?'highpass':'lowpass';f.frequency.value=hp||1200;g.gain.setValueAtTime(vol,t);g.gain.exponentialRampToValueAtTime(.0004,t+d);s.connect(f);f.connect(g);g.connect(dest);s.start(t);s.stop(t+d+.02)}
// ---- sound effects
const AUDFX={
 move:(c,t,d)=>audTone(520,t,.06,'square',.12,d),
 sel:(c,t,d)=>{audTone(660,t,.08,'square',.14,d);audTone(990,t+.06,.12,'square',.12,d)},
 back:(c,t,d)=>audTone(420,t,.1,'triangle',.2,d,260),
 step:(c,t,d)=>audNoise(t,.05,.16,d,500),
 pick:(c,t,d)=>{audTone(780,t,.09,'triangle',.3,d);audTone(1170,t+.07,.14,'triangle',.3,d)},
 gem:(c,t,d)=>{[784,988,1319].forEach((f,i)=>audTone(f,t+i*.06,.18,'sine',.3,d))},
 coin:(c,t,d)=>{audTone(1319,t,.07,'square',.12,d);audTone(1760,t+.07,.25,'square',.12,d)},
 talk:(c,t,d)=>{for(let i=0;i<3;i++)audTone(300+audR()*220,t+i*.05,.06,'square',.08,d)},
 hurt:(c,t,d)=>{audTone(300,t,.35,'sawtooth',.25,d,70);audNoise(t,.2,.25,d,300)},
 lose:(c,t,d)=>{[392,330,262,196].forEach((f,i)=>audTone(f,t+i*.18,.3,'triangle',.3,d))},
 win:(c,t,d)=>{[523,659,784,1047,784,1047,1319].forEach((f,i)=>{audTone(f,t+i*.13,.3,'square',.1,d);audTone(f/2,t+i*.13,.3,'triangle',.2,d)});for(let i=0;i<6;i++)audNoise(t+.9+i*.12,.08,.15,d,3000)},
 boss:(c,t,d)=>{[392,523,659,784,1047,1319,1568].forEach((f,i)=>{audTone(f,t+i*.11,.4,'square',.1,d);audTone(f/2,t+i*.11,.4,'sawtooth',.1,d)});audNoise(t+.8,.6,.2,d,2000)},
 splash:(c,t,d)=>{audNoise(t,.25,.3,d,900);audTone(300,t,.2,'sine',.2,d,120)},
 reel:(c,t,d)=>{audTone(900,t,.05,'square',.08,d);audTone(1100,t+.05,.05,'square',.08,d)},
 catch:(c,t,d)=>{[523,659,784,1047].forEach((f,i)=>audTone(f,t+i*.08,.2,'triangle',.3,d))},
 eat:(c,t,d)=>{for(let i=0;i<3;i++)audNoise(t+i*.09,.06,.25,d,700)},
 build:(c,t,d)=>{audTone(110,t,.15,'sine',.5,d,60);audNoise(t,.08,.3,d,300);audTone(110,t+.14,.15,'sine',.5,d,60);audNoise(t+.14,.08,.3,d,300)},
 siren:(c,t,d)=>{for(let i=0;i<4;i++)audTone(i%2?640:880,t+i*.45,.45,'sawtooth',.12,d)},
 plant:(c,t,d)=>{audTone(200,t,.15,'sine',.4,d,120);audNoise(t,.1,.2,d,400)},
 swoosh:(c,t,d)=>audNoise(t,.2,.2,d,1500),
 chime:(c,t,d)=>{audTone(988,t,.3,'sine',.25,d);audTone(1319,t+.08,.4,'sine',.2,d)}
};
function sfx(n){try{if(!AUD.s||!AUD.ctx||AUD.ctx.state!='running'||typeof BOT!='undefined'&&BOT.on)return;const f=AUDFX[n];if(f)f(AUD.ctx,AUD.ctx.currentTime+.005,AUD.sg)}catch(e){}}
// ---- soundtrack (three procedural tracks)
const AUDT={
 calm:{bpm:78,root:57,sc:[0,3,5,7,10],ch:[[0,7,12],[-4,3,8],[3,10,15],[-2,5,10]],lead:'sine',bass:'sine',hat:0,arp:1},
 farm:{bpm:108,root:60,sc:[0,2,4,7,9],ch:[[0,4,7],[-5,2,7],[-3,0,4],[-7,0,5]],lead:'triangle',bass:'triangle',hat:1,arp:0},
 action:{bpm:134,root:62,sc:[0,2,3,5,7,8,10],ch:[[0,3,7],[-4,0,3],[-9,-2,3],[-7,-3,0]],lead:'square',bass:'sawtooth',hat:1,arp:0}
};
function audWant(){const m=typeof mode=='undefined'?'start':mode;if(m=='maze'||m=='ms')return'action';if(m=='play'||m=='fg')return'farm';return'calm'}
function audSched(){const c=AUD.ctx;if(!c||c.state!='running'||!AUD.m)return;const w=audWant();if(w!=AUD.track){AUD.track=w;AUD.step=0;AUD.next=Math.max(AUD.next,c.currentTime+.05)}
 const T=AUDT[AUD.track],sp=60/T.bpm/2;let guard=0;while(AUD.next<c.currentTime+.3&&guard++<8){const s=AUD.step,t=AUD.next,bar=(s>>3)&3,b8=s&7,ch=T.ch[bar],d=AUD.mg;
  if(T.arp){const n=T.root+ch[[0,1,2,1,2,1,0,1][b8]%3];audTone(audMidi(n),t,sp*2.2,'sine',.16,d,0,.02)}
  if(b8==0||(T.hat&&b8==4)||(AUD.track=='action'&&b8%2==0)){const bn=T.root-24+ch[0];audTone(audMidi(bn),t,sp*(AUD.track=='action'?.9:1.8),T.bass,AUD.track=='action'?.12:.2,d)}
  if(!T.arp){if(b8==0||b8==3||b8==6||(AUD.track=='action')){const pat=[0,1,2,1,0,2,1,2];const n=T.root+ch[pat[b8]%3]}}
  if(T.lead&&!T.arp&&(b8%2==0||audR()<.35)&&audR()<.85){const sc=T.sc,deg=sc[Math.floor(audR()*sc.length)],oct=audR()<.3?24:12,n=T.root+ch[0]+deg+oct-12;audTone(audMidi(n),t,sp*(1+audR()*1.4),T.lead,AUD.track=='action'?.05:.11,d)}
  if(T.arp&&b8==0&&audR()<.6){const sc=T.sc,n=T.root+12+sc[Math.floor(audR()*sc.length)];audTone(audMidi(n+12),t+sp,sp*3,'triangle',.07,d,0,.05)}
  if(T.hat&&b8%2==1)audNoise(t,.03,.05,d,6000);
  if(AUD.track=='action'&&(b8==2||b8==6))audNoise(t,.06,.07,d,2500);
  AUD.next+=sp;AUD.step++}}
// ---- hook events
function audWrap(n,fx,pre){try{const f0=eval(n);const w=function(){const r=f0.apply(this,arguments);try{if(fx)sfx(typeof fx=='function'?fx(r,arguments):fx)}catch(e){}return r};eval(n+'=w')}catch(e){}}
audWrap('msHurt','hurt');audWrap('msWin',()=>(MS.L&&MS.L.lv%10==0)?'boss':'win');audWrap('mzWin','win');audWrap('msSay','chime');
audWrap('fishCast','swoosh');audWrap('fishHook','reel');audWrap('fishCatch','catch');audWrap('fishLose','back');
audWrap('fbuy','coin');audWrap('sellAll','coin');audWrap('wEat','eat');audWrap('eatDish','eat');audWrap('wPickFz','pick',1);audWrap('wPlaceTry',(r)=>r?'build':null);audWrap('wCollapse','siren');audWrap('tplant','plant');audWrap('ftalk','talk');audWrap('talk','talk');audWrap('fxtalk','talk');audWrap('iTalk','talk');audWrap('jtalk','talk');audWrap('mazeStart','swoosh');audWrap('msStart','swoosh');
