const audP0=press;press=function(k){audResume();try{const um=['start','menu','fgmenu','msmenu','alm','ms_sel'];if(um.indexOf(mode)>=0){if(k=='ArrowUp'||k=='ArrowDown'||k=='ArrowLeft'||k=='ArrowRight'||k=='w'||k=='s'||k=='a'||k=='d')sfx('move');else if(k=='Enter'||k==' '||k=='e')sfx('sel');else if(k=='Escape')sfx('back')}}catch(e){}return audP0.apply(this,arguments)};
