function sLay(n){const st=n>6?36:n>5?40:n>4?46:54;return{st,y0:n>6?138:n>5?146:160,h:st-6}}
function startD(t){scene(t,[1,1,1,1,1]);
 g.fillStyle='rgba(8,6,20,.5)';g.fillRect(0,0,640,448);
 for(let i=0;i<30;i++){const a=t*.6+i*2.1;g.fillStyle='rgba(255,240,120,'+(.3+.5*Math.abs(Math.sin(t*2+i)))+')';g.fillRect((i*53+Math.sin(a)*40+640)%640,(i*37+t*8)%448,3,3)}
 txt('LANTERN WOODS',320,62,38,UI.edge,'center',1);txt('MOONLIGHTING ON A RANCH',320,90,15,'#f6d878','center',1);txt('A Farm Sim About Having Too Many Jobs',320,110,10,UI.txt,'center');
 const it=startItems();sSel=Math.min(sSel,it.length-1);const L=sLay(it.length);
 g.fillStyle='rgba(6,4,14,.55)';g.fillRect(150,L.y0-8,340,it.length*L.st+8);g.strokeStyle='#4a341a';g.strokeRect(150.5,L.y0-7.5,339,it.length*L.st+7);
 it.forEach((m,i)=>{const y=L.y0+i*L.st,sel=i==sSel;g.fillStyle=sel?'rgba(232,200,96,.3)':'rgba(40,28,14,.7)';g.fillRect(166,y,308,L.h);g.strokeStyle=sel?UI.edge:'#6a4a22';g.lineWidth=sel?2:1;g.strokeRect(166,y,308,L.h);g.lineWidth=1;txt(m[0],320,y+L.h/2+5,sel?15:14,sel?'#fff':UI.txt,'center',sel)});
 spr('lantern',118+Math.sin(t*6)*2,L.y0+sSel*L.st-2,36);
 const dsc=it[sSel][1],d1=dsc.length>78?dsc.slice(0,76)+'..':dsc;txt(d1,320,L.y0+it.length*L.st+16,9,'#e8d9a8','center');
 txt('Up/Down + Enter, or click',320,430,10,UI.dim,'center')}
