// ===== v8z part 1: weather system =====
const WXN={clear:'Clear',partly:'Partly',cloudy:'Cloudy',fog:'Fog',windy:'Windy',heat:'Hot',drizzle:'Drizzle',rain:'Rain',tstorm:'Thunder',hurricane:'HURRICANE',snow:'Snow',blizzard:'Blizzard'};
const WXL={clear:'Clear and sunny',partly:'Partly cloudy',cloudy:'Overcast',fog:'Foggy morning',windy:'Windy',heat:'Heat wave',drizzle:'Light drizzle',rain:'Steady rain',tstorm:'Thunderstorm',hurricane:'HURRICANE',snow:'Snowfall',blizzard:'Blizzard'};
const WX={fl:0,bolt:null,nextL:0,thAt:0,last:0,force:null,seed:11,amb:null};
function wxR(){WX.seed=(WX.seed*1664525+1013904223)>>>0;return WX.seed/4294967296}
function wxHash(d,s){return(((d*2654435761+s*40503)>>>0)%1000)/1000}
function wxKindFor(day,w,s){const h=wxHash(day,1);let k;
 if(w=='storm')k='hurricane';else if(w=='rain')k=h<.28?'drizzle':h<.72?'rain':'tstorm';else if(w=='snow')k=h<.7?'snow':'blizzard';
 else{k=h<.38?'clear':h<.6?'partly':h<.76?'cloudy':h<.88?'fog':'windy';if(s==1&&h>.45&&h<.8)k='heat'}return k}
function wxKind(){if(WX.force)return WX.force;if(!FG.on)return'clear';return wxKindFor(FG.day,FG.weather,fseason())}
function wxKindTmrw(){return wxKindFor(FG.day+1,FG.fcast,sdy(FG.day+1))}
const WXOFF={clear:3,partly:1,cloudy:-2,fog:-4,windy:-3,heat:11,drizzle:-4,rain:-6,tstorm:-5,hurricane:-8,snow:-6,blizzard:-12};
function wxTemp(day,k,s,min){day=day==null?FG.day:day;k=k||wxKind();s=s==null?fseason():s;min=min==null?FG.min:min;return Math.round([60,82,54,26][s]+WXOFF[k]+(wxHash(day,2)*8-4)+6*Math.sin((min/60-9)/24*Math.PI*2))}
const wxRainy=k=>k=='drizzle'||k=='rain'||k=='tstorm'||k=='hurricane';
const wxSnowy=k=>k=='snow'||k=='blizzard';
function wxIcon(k,x,y){const G=(c,a,b,w,h)=>{g.fillStyle=c;g.fillRect(x+a,y+b,w,h)};
 const cloud=c=>{G(c,1,3,10,5);G(c,3,1,5,3)};
 if(k=='clear'){G('#ffd84a',2,2,8,8);G('#ffd84a',5,0,2,12);G('#ffd84a',0,5,12,2)}
 else if(k=='heat'){G('#ff9a3a',2,2,8,8);G('#ffd84a',4,4,4,4);G('#ff6a2a',5,0,2,2);G('#ff6a2a',5,10,2,2);G('#ff6a2a',0,5,2,2);G('#ff6a2a',10,5,2,2)}
 else if(k=='partly'){G('#ffd84a',5,0,6,6);cloud('#d8dee8')}
 else if(k=='cloudy'){cloud('#aab4c2');G('#c8d0dc',0,5,6,4)}
 else if(k=='fog'){G('#c8ccd4',0,2,12,2);G('#aab0bc',1,5,10,2);G('#c8ccd4',0,8,12,2)}
 else if(k=='windy'){G('#c8d4e0',0,3,9,1);G('#c8d4e0',8,2,2,2);G('#c8d4e0',2,6,10,1);G('#c8d4e0',11,5,1,2);G('#c8d4e0',0,9,7,1)}
 else if(k=='drizzle'){cloud('#9aa6b4');G('#7ac0f0',3,9,1,2);G('#7ac0f0',7,10,1,2)}
 else if(k=='rain'){cloud('#8a96a6');G('#5ab0f0',2,9,1,3);G('#5ab0f0',6,9,1,3);G('#5ab0f0',9,8,1,3)}
 else if(k=='tstorm'||k=='hurricane'){cloud(k=='hurricane'?'#5a5a6e':'#6a7080');G('#ffe040',5,7,2,2);G('#ffe040',3,9,3,2);G('#ffe040',6,11,1,1)}
 else if(k=='snow'){cloud('#dfe6ee');G('#fff',2,9,2,2);G('#fff',6,10,2,2);G('#fff',9,8,2,2)}
 else if(k=='blizzard'){cloud('#c8d0dc');G('#fff',1,8,2,2);G('#fff',5,9,2,2);G('#fff',9,8,2,2);G('#fff',3,11,2,1)}}
function wxIndoor(){return FG.sc=='in'}
function wxFlash(){if(WX.fl>0)return;WX.fl=1;WX.fl0=performance.now();const L=wxIndoor()?0:1;WX.bolt=null;if(L){const pts=[];let x=60+wxR()*520,y=0;pts.push([x,y]);for(let i=0;i<9;i++){x+=(wxR()-.5)*60;y+=26+wxR()*18;pts.push([x,y])}WX.bolt=pts}WX.thAt=performance.now()+500+wxR()*1700}
function wxDraw(t,sc){const k=wxKind(),now=performance.now(),dt=Math.min(.1,(now-(WX.last||now))/1000);WX.last=now;
 if(sc=='in')return;const s=fseason(),min=FG.min||540,tod=(min-360)/720;
 // lightning scheduling
 if(k=='tstorm'||k=='hurricane'){if(!WX.nextL)WX.nextL=now+2500+wxR()*5000;if(now>WX.nextL){wxFlash();WX.nextL=now+(k=='hurricane'?2500+wxR()*4500:6000+wxR()*10000)}}
 if(WX.thAt&&now>WX.thAt){WX.thAt=0;if(typeof sfx=='function')sfx('thunder')}
 g.save();
 // sky tint / clouds
 const dark={cloudy:.10,drizzle:.14,rain:.2,tstorm:.34,hurricane:.45,snow:.08,blizzard:.14,fog:.05,partly:.0,windy:.04,clear:0,heat:0}[k];
 if(dark){g.fillStyle=k=='hurricane'||k=='tstorm'?'rgba(10,10,34,'+dark+')':'rgba(36,44,66,'+dark+')';g.fillRect(0,0,640,448)}
 if(k=='partly'||k=='cloudy'||k=='windy'||k=='drizzle'||k=='rain'||k=='tstorm'||k=='snow'){const n=k=='partly'?3:6,a=k=='partly'?.10:.14;for(let i=0;i<n;i++){const cx=((t*(6+i*1.3)+i*190)%900)-140,cy=60+((i*83)%320);g.fillStyle='rgba(10,16,30,'+a+')';g.beginPath();g.ellipse(cx,cy,110+i%3*20,34+i%2*10,0,0,7);g.fill();g.beginPath();g.ellipse(cx+60,cy+14,80,26,0,0,7);g.fill()}}
 // fog
 if(k=='fog'||k=='drizzle'||k=='hurricane'){const lv=k=='fog'?Math.max(.3,1-Math.max(0,min-360)/420):.22;g.fillStyle='rgba(214,220,230,'+(.34*lv)+')';g.fillRect(0,0,640,448);for(let j=0;j<7;j++){const cx=((t*(4+j)+j*140)%880)-120;g.fillStyle='rgba(224,228,236,'+(.22*lv)+')';g.beginPath();g.ellipse(cx,50+j*58,230,28,0,0,7);g.fill()}}
 // heat
 if(k=='heat'){g.fillStyle='rgba(255,196,90,.07)';g.fillRect(0,0,640,448);for(let y=20;y<430;y+=36){g.fillStyle='rgba(255,244,210,.05)';g.fillRect(Math.sin(t*2.2+y)*6,y+Math.sin(t*3+y)*3,640,7)}}
 // golden hour / dawn mist
 if((k=='clear'||k=='partly'||k=='heat')&&min>=1020&&min<1080){g.fillStyle='rgba(255,140,60,'+(.12*(min-1020)/60)+')';g.fillRect(0,0,640,448)}
 // rainbow after rain
 if(FG.pw=='rain'&&(k=='clear'||k=='partly')&&min>=420&&min<800){const a=.22*Math.min(1,(min-420)/60)*Math.min(1,(800-min)/80),cols=['#ff5a5a','#ff9a3a','#ffe03a','#5ae05a','#5ab4ff','#7a6aff'];g.lineWidth=4;cols.forEach((c,i)=>{g.strokeStyle=c;g.globalAlpha=a;g.beginPath();g.arc(330,380,230-i*4,Math.PI*1.08,Math.PI*1.92);g.stroke()});g.globalAlpha=1}
 // rain
 if(wxRainy(k)){const n={drizzle:40,rain:95,tstorm:130,hurricane:190}[k],wx=k=='hurricane'?.7:k=='tstorm'?.28:.1,sp=k=='drizzle'?260:420;g.strokeStyle=k=='drizzle'?'rgba(200,215,240,.5)':'rgba(200,220,255,.75)';g.lineWidth=1;g.beginPath();
  for(let i=0;i<n;i++){const y=((i*37.3+t*sp*(.85+(i%5)*.06))%478)-15,x=(((i*91.7)%700)-y*wx+t*wx*30+1400)%680-20;g.moveTo(x,y);g.lineTo(x-wx*10,y+10)}g.stroke();
  g.lineWidth=1;const rp=k=='drizzle'?10:k=='rain'?18:26;for(let i=0;i<rp;i++){const ph=(t*1.7+i*.37)%1,x=(i*97.3+i*i*7)%640,y=60+(i*53.1)%320;g.strokeStyle='rgba(200,220,255,'+((1-ph)*.45)+')';g.beginPath();g.ellipse(x,y,ph*6,ph*2.4,0,0,7);g.stroke()}}
 // snow
 if(wxSnowy(k)){const bl=k=='blizzard',n=bl?170:75,wx=bl?1.4:.18;g.fillStyle='rgba(255,255,255,.85)';for(let i=0;i<n;i++){const y=((i*37+t*(bl?150:46)*(.7+(i%4)*.18))%470)-10,x=(((i*71)%700)+Math.sin(t*1.3+i)*(bl?10:18)+t*wx*60+1400)%680-20,z=i%3?2:3;g.fillRect(x,y,z,z)}if(bl){g.fillStyle='rgba(235,240,250,.2)';g.fillRect(0,0,640,448)}}
 // wind-blown leaves / petals / flakes
 if(k=='windy'||k=='tstorm'||k=='hurricane'||k=='blizzard'||(k=='partly'&&(s==0||s==2))){const n=k=='windy'||k=='hurricane'?30:k=='partly'?9:14,col=[['#f4a8c8','#fff0f6'],['#bfe08a','#e8f0a8'],['#d9792a','#c04a1a'],['#ffffff','#dfe6f0']][s];for(let i=0;i<n;i++){const sp=k=='partly'?40:k=='windy'?95:160,x=((i*67+t*sp*(.6+(i%5)*.15))%700)-30,y=(i*41+Math.sin(t*1.4+i)*26+t*14*(i%3))%440;g.fillStyle=col[i%2];g.save();g.translate(x,y);g.rotate(t*3+i);g.fillRect(-2,-1,4,2);g.restore()}}
 // lightning
 if(WX.fl>0){const e=(now-WX.fl0)/1000,a=e<.08?.6:e<.16?.15:e<.24?.5:e<.5?.5*(1-(e-.24)/.26):0;if(e>.5){WX.fl=0;WX.bolt=null}else{g.fillStyle='rgba(235,240,255,'+(wxIndoor()?a*.3:a)+')';g.fillRect(0,0,640,448);if(WX.bolt&&e<.3){g.strokeStyle='rgba(255,255,255,.95)';g.lineWidth=2;g.beginPath();WX.bolt.forEach((p,i)=>i?g.lineTo(p[0],p[1]):g.moveTo(p[0],p[1]));g.stroke();g.strokeStyle='rgba(170,190,255,.5)';g.lineWidth=5;g.stroke()}}}
 g.restore()}
// ---- ambience audio (rain / wind loops)
function wxAmb(){try{const c=AUD.ctx;if(!c||c.state!='running'||!AUD.nb)return;if(!WX.amb){const mk=(type,f,q)=>{const s=c.createBufferSource();s.buffer=AUD.nb;s.loop=true;const fl=c.createBiquadFilter();fl.type=type;fl.frequency.value=f;fl.Q.value=q;const gn=c.createGain();gn.gain.value=0;s.connect(fl);fl.connect(gn);gn.connect(AUD.sg);s.start();return gn};WX.amb={rain:mk('bandpass',3200,.4),wind:mk('lowpass',420,.8)}}
 let r=0,w=0;if(typeof FG!='undefined'&&FG.on&&mode=='fg'){const k=wxKind(),v=wxIndoor()?.3:1;r=({drizzle:.05,rain:.11,tstorm:.17,hurricane:.2})[k]||0;w=({windy:.1,tstorm:.05,hurricane:.24,blizzard:.2,fog:.01})[k]||0;r*=v;w*=v;w*=.75+.25*Math.sin(performance.now()/1700)}
 WX.amb.rain.gain.setTargetAtTime(r,c.currentTime,.5);WX.amb.wind.gain.setTargetAtTime(w,c.currentTime,.5)}catch(e){}}
setInterval(wxAmb,300);
AUDFX.thunder=(c,t,d)=>{const v=wxIndoor()?.5:1;audNoise(t,1.8,.55*v,d,180);audNoise(t+.25,1.3,.4*v,d,110);audTone(70,t,1.6,'sine',.4*v,d,28);audTone(48,t+.2,1.4,'sine',.35*v,d,22)};
// remember yesterday's weather (rainbow after rain)
const wxN0=fnewday;fnewday=function(pass){if(FG.on)FG.pw=FG.weather;WX.nextL=0;return wxN0.apply(this,arguments)};
// HUD: richer weather label + temperature
const wxH0=fhud;fhud=function(t){wxH0(t);if(!FG.on)return;const HC=UIS&&UIS.hc,k=wxKind();g.fillStyle=HC?'#000':'#150d07';g.fillRect(222,4,72,20);wxIcon(k,224,6);txt(WXN[k],238,15,8,HC?'#fff':UI.txt);txt(wxTemp()+'°F',238,23,7,UI.dim)};

// ===== v8z part 2: minimap, world map, villager tracking, waypoints =====
const WPC=['#ff5a5a','#5ab4ff','#ffd24a','#6ae06a','#d07aff'],MAPSC=['ranch','town','mtn'];
const MAPN={ranch:'Ranch',town:'Town',mtn:'Mountain','in':'Indoors'};
const MAPBN={house:'Your Cabin',barn:'Barn',coop:'Chicken Coop',bin:'Shipping Bin',well:'Well',mail:'Mailbox',mayor:"Mayor's Office",lib:'Library',flowers:'Florist',church:'Church',seeds:"Ned's Seeds",dealer:'Dealer',lumber:'Lumber Yard',bar:'Bar',fountain:'Fountain',springs:'Hot Springs',cave:'Cave',stairs:'Mountain Path'};
const MAPBC={house:'#b0643c',barn:'#a8442c',coop:'#c88a4a',bin:'#8a6a3a',well:'#7a8a9a',mail:'#4a90e0',mayor:'#8a5a8a',lib:'#5a6aa8',flowers:'#d87aa8',church:'#d8d8e0',seeds:'#6aa84a',dealer:'#a8883a',lumber:'#8a6a3a',bar:'#9a4a3a',fountain:'#5aa8d8',springs:'#78c8d8',cave:'#3a3a48',stairs:'#9a9a9a'};
const MAPAD={ranch:['town'],town:['ranch','mtn'],mtn:['town']};
const MAPEXIT={'ranch>town':()=>[19.9,6],'town>ranch':()=>[-.2,6],'town>mtn':()=>[18.6,-.2],'mtn>town':()=>[10,12.8]};
const MAPARR={'ranch>town':py=>[.06,py],'town>ranch':py=>[19.2,py],'town>mtn':()=>[10,11],'mtn>town':()=>[18,2]};
const wpL=()=>(FG.wp||(FG.wp=[]));
function wpHop(a,b){const q=[[a,[a]]],seen={[a]:1};while(q.length){const[c,p]=q.shift();if(c==b)return p;for(const n of MAPAD[c]||[])if(!seen[n]){seen[n]=1;q.push([n,p.concat(n)])}}return null}
function wpRoute(w){let px=FG.x/32,py=FG.y/32,d=0,hop=null,cur=FG.sc;
 if(cur=='in'){hop=[9.5,11.6];d+=Math.hypot(9.5-px,11-py);px=(FG.outX||0)/32;py=(FG.outY||0)/32;cur=FG.outSc||'town'}
 const path=wpHop(cur,w.sc);if(!path)return null;
 for(let i=0;i<path.length-1;i++){const k=path[i]+'>'+path[i+1],ex=MAPEXIT[k]();if(k=='ranch>town'||k=='town>ranch')ex[1]=Math.max(.5,Math.min(11.5,py));if(!hop)hop=ex;d+=Math.hypot(ex[0]-px,ex[1]-py);const ar=MAPARR[k](py);px=ar[0];py=ar[1]}
 d+=Math.hypot(w.x+.5-px,w.y+.5-py);if(!hop)hop=[w.x+.5,w.y+.5];return{d,hop,cross:path.length>1||FG.sc=='in'}}
function wpActive(){const L=wpL();if(!L.length)return null;if(FG.wpSel==null||FG.wpSel>=L.length)FG.wpSel=0;return L[FG.wpSel]}
function wpUpdate(){const L=wpL();for(let i=L.length-1;i>=0;i--){const w=L[i];if(w.tr!=null){let p=null;try{p=npcPos(w.tr)}catch(e){}if(p){w.sc=p.sc;w.x=Math.round(p.x);w.y=Math.round(p.y);w.away=0}else w.away=1}
  else if(w.sc==FG.sc&&Math.hypot(w.x+.5-(FG.x/32+.5),w.y+.5-(FG.y/32+.5))<.9){L.splice(i,1);if(FG.wpSel>=L.length)FG.wpSel=Math.max(0,L.length-1);fsay('Arrived at '+w.n+'.');try{sfx('chime')}catch(e){}}}}
function wpAdd(sc,x,y,tr){const L=wpL();let j=tr!=null?L.findIndex(w=>w.tr==tr):L.findIndex(w=>w.tr==null&&w.sc==sc&&w.x==x&&w.y==y);
 if(j>=0){const n=L[j].n;L.splice(j,1);if(FG.wpSel>=L.length)FG.wpSel=Math.max(0,L.length-1);fsay('Removed: '+n);try{sfx('back')}catch(e){}return 0}
 if(L.length>=5){fsay('Five waypoints max. Remove one first.');return 0}
 const used=L.map(w=>w.c),c=WPC.find(c=>!used.includes(c))||WPC[0];let n;
 if(tr!=null)n=NPCS_[tr].n;else{const d=mapDescribe(sc,x,y);if(d.b)n=d.b;else{let i=1;while(L.some(w=>w.n=='Pin '+i))i++;n='Pin '+i}}
 L.push({sc,x,y,n,c,tr:tr==null?null:tr});FG.wpSel=L.length-1;fsay('Waypoint set: '+n);try{sfx('pick')}catch(e){}return 1}
function mapDescribe(sc,x,y){const r={t:'Open ground',b:null};const o=(OB[sc]||[]).find(o=>x>=o.x&&x<o.x+o.w&&y>=o.y&&y<o.y+o.h);if(o){r.b=MAPBN[o.id]||o.id;r.t=r.b;return r}
 const bb=mapBldDoor(sc,x,y);if(bb){r.b=bb;r.t=bb+' (entrance)';return r}
 if(sc=='mtn'&&x>=POND.x1&&x<=POND.x2&&y>=POND.y1&&y<=POND.y2)r.t='Pond';
 else if(FG.fz){const f=FG.fz.find(f=>f.sc==sc&&f.x==x&&f.y==y&&f.k!='rock');if(f)r.t='Forage: '+(INAME[f.k]||f.k)}
 if(r.t=='Open ground'&&sc=='ranch'&&FG.crop&&FG.crop[x+','+y])r.t='Crop: '+(FG.crop[x+','+y].k);return r}
function mapBldDoor(sc,x,y){for(const o of OB[sc]||[])if(INT[o.id]&&y==o.y+o.h&&x==doorA(o))return MAPBN[o.id]||o.id;return null}
// ---- tile layers (cached 1s)
const MAPC={};
function mapLayer(sc){const now=performance.now();let c=MAPC[sc];if(c&&now-c.t<1000&&c.d==FG.day)return c.cv;const cv=c?c.cv:document.createElement('canvas');cv.width=20;cv.height=13;const x=cv.getContext('2d'),s0=FG.sc,gr={ranch:'#4f8a3c',town:'#b89a62',mtn:'#5f7f5a','in':'#8a6a44'}[sc];
 FG.sc=sc;try{for(let ty=0;ty<13;ty++)for(let tx=0;tx<20;tx++){let col=gr;try{const o=sc=='in'?null:fobAt(tx,ty);if(o)col=MAPBC[o.id]||'#888';else if(sc=='mtn'&&fwater(tx,ty))col='#3a78c8';else{let b=null;try{b=typeof wBldAt=='function'&&sc!='in'?wBldAt(sc,tx,ty):null}catch(e){}if(b)col='#9a7a4a';else if(fsolid(tx,ty))col=sc=='in'?'#4a3420':'#2d5a2a';else if(sc=='town'&&(ty==6||ty==7)&&tx>0)col='#a88a54';else if(sc=='ranch'&&tx>=1&&tx<=11&&ty>=1&&ty<=9&&((tx+ty)&1))col='#487e36'}}catch(e){}x.fillStyle=col;x.fillRect(tx,ty,1,1)}
  if(sc!='in')for(const o of OB[sc]||[])if(INT[o.id]){const dx=doorA(o);x.fillStyle='#ffe9a8';x.fillRect(dx,o.y+o.h-1,1,1)}}catch(e){}finally{FG.sc=s0}
 MAPC[sc]={cv,t:now,d:FG.day};return cv}
// ---- entities in a scene (tile coords, centre)
function mapEnts(sc){const E=[];
 for(let i=0;i<NPCS_.length;i++){let p=null;try{p=npcPos(i)}catch(e){}if(p&&p.sc==sc)E.push({k:'npc',x:p.x+.5,y:p.y+.5,c:NPCS_[i].c,n:NPCS_[i].n,i})}
 if(sc=='in'&&typeof INR!='undefined'&&INR.list)for(const p of INR.list)E.push({k:'npc',x:p.x/32+.5,y:p.y/32+.5,c:'#e8c070',n:p.n||'Visitor',i:-1});
 if(sc=='town'&&fdow()==6&&FG.weather=='sun')E.push({k:'ped',x:17.5,y:5.5,c:'#c070e0',n:'Peddler',i:-2});
 if(sc=='ranch'){(FG.cows||[]).forEach((c,i)=>E.push({k:'cow',x:13+(i%3)*2+.9,y:9+((i/3)|0)*1.4+.6}));(FG.hens||[]).forEach((h,i)=>E.push({k:'hen',x:17+(i%4)+.3,y:8.6+((i/4)|0)*.8+.4}));if(FG.flags&&FG.flags.horse)E.push({k:'cow',x:11.6,y:10.6});
  for(const k in FG.crop||{}){const[x,y]=k.split(',').map(Number),c=FG.crop[k],cr=CR[c.k];E.push({k:c.a>=cr.d?'ripe':'crop',x:x+.5,y:y+.5})}
  for(const tr of FG.trees||[])E.push({k:'tree',x:tr.x+.5,y:tr.y+.5,m:typeof tstage=='function'&&tstage(tr)==2})}
 if(sc=='mtn')for(const m of FG.mtn||[])E.push({k:'fz',x:m.x+.5,y:m.y+.5});
 for(const f of FG.fz||[])if(f.sc==sc&&f.k!='rock')E.push({k:'fz',x:f.x+.5,y:f.y+.5});
 if(FG.flags&&FG.flags.dog&&typeof NPR!='undefined'&&NPR.dog&&NPR.dog.sc==sc)E.push({k:'dog',x:NPR.dog.x/32+.5,y:NPR.dog.y/32+.5});
 return E}
function mapPlayerPos(){return{x:FG.x/32+.5,y:FG.y/32+.6}}
function mapDot(e,X,Y,s,big){const R=Math.max(1.4,s*.34);
 if(e.k=='npc'||e.k=='ped'){g.fillStyle=e.c;g.beginPath();g.arc(X,Y,big?R+1.2:R+.6,0,7);g.fill();g.strokeStyle='#fff';g.lineWidth=1;g.stroke();if(big&&e.n)txt(e.n[0],X,Y+2.5,7,'#fff','center',1)}
 else if(e.k=='cow'){g.fillStyle='#f0ece0';g.fillRect(X-1.5,Y-1,3,2)}else if(e.k=='hen'){g.fillStyle='#e8c070';g.fillRect(X-1,Y-1,2,2)}
 else if(e.k=='dog'){g.fillStyle='#8a5a2a';g.fillRect(X-1.5,Y-1,3,2)}
 else if(e.k=='fz'){g.fillStyle='#ffe27a';g.fillRect(X-1,Y-1,2,2);g.fillStyle='#fff';g.fillRect(X-.5,Y-.5,1,1)}
 else if(e.k=='crop'){g.fillStyle='#8fe070';g.fillRect(X-.5,Y-.5,1.5,1.5)}else if(e.k=='ripe'){g.fillStyle='#ff9a3a';g.fillRect(X-1,Y-1,2,2)}
 else if(e.k=='tree'){g.fillStyle=e.m?'#3f9a3a':'#8fd070';g.fillRect(X-1,Y-1,2,2)}}
function mapArrow(x,y,ang,sz,col){g.save();g.translate(x,y);g.rotate(ang);g.fillStyle=col;g.strokeStyle='#000';g.lineWidth=1;g.beginPath();g.moveTo(sz,0);g.lineTo(-sz*.7,-sz*.75);g.lineTo(-sz*.3,0);g.lineTo(-sz*.7,sz*.75);g.closePath();g.fill();g.stroke();g.restore()}
function mapFlag(x,y,col,sz){g.fillStyle='#000';g.fillRect(x-.5,y-sz,2,sz+1);g.fillStyle='#eee';g.fillRect(x,y-sz,1,sz);g.fillStyle=col;g.beginPath();g.moveTo(x+1,y-sz);g.lineTo(x+1+sz*.9,y-sz*.7);g.lineTo(x+1,y-sz*.4);g.closePath();g.fill();g.strokeStyle='#000';g.lineWidth=.6;g.stroke()}
function mapFacing(){return[Math.PI/2,0,-Math.PI/2,Math.PI][FG.d|0]||0}
// ---- in-world waypoint markers
function wpWorld(t,sc){if(!FG.on||BOT.on||sc=='in')return;wpUpdate();const L=wpL(),act=wpActive();if(!L.length)return;
 L.forEach((w,i)=>{if(w.sc!=sc)return;const X=w.x*32+16,Y=w.y*32+4+Math.sin(t*4+i)*2,sel=w==act;g.globalAlpha=.9;g.fillStyle=w.c;g.beginPath();g.moveTo(X,Y+14);g.lineTo(X-7,Y);g.lineTo(X+7,Y);g.closePath();g.fill();g.strokeStyle='#000';g.lineWidth=1;g.stroke();if(sel){g.strokeStyle=w.c;g.globalAlpha=.5+.4*Math.sin(t*5);g.strokeRect(w.x*32+2,w.y*32+2,28,28)}g.globalAlpha=1;const lab=w.n+(w.away?' (away)':'');g.fillStyle='rgba(0,0,0,.6)';g.fillRect(X-lab.length*2.6-2,Y-12,lab.length*5.2+4,10);txt(lab,X,Y-4,8,'#fff','center')});
 if(act&&act.sc!=sc){const r=wpRoute(act);if(r&&r.hop){const hx=Math.max(14,Math.min(626,r.hop[0]*32)),hy=Math.max(38,Math.min(404,r.hop[1]*32));const ang=Math.atan2(r.hop[1]-(FG.y/32+.5),r.hop[0]-(FG.x/32+.5));g.globalAlpha=.65+.35*Math.sin(t*6);mapArrow(hx,hy,ang,10,act.c);g.globalAlpha=1;const lab='to '+act.n+' ('+MAPN[act.sc]+')';const lx=Math.max(lab.length*2.6+6,Math.min(634-lab.length*2.6,hx));g.fillStyle='rgba(0,0,0,.65)';g.fillRect(lx-lab.length*2.6-2,hy+(hy<200?14:-24),lab.length*5.2+4,10);txt(lab,lx,hy+(hy<200?22:-16),8,'#fff','center')}}}
// ---- minimap
function mmRect(){const touch=typeof matchMedia!='undefined'&&matchMedia('(pointer:coarse)').matches;return{x:528,y:touch?32:310,w:108,h:86}}
mmap=function(){if(!FG.on||FG.ui||!UIS.mini)return;const R=mmRect(),sc=FG.sc,s=5,mx=R.x+4,my=R.y+4;
 g.fillStyle='rgba(14,10,6,.86)';g.fillRect(R.x,R.y,R.w,R.h);g.strokeStyle=UI.edge;g.lineWidth=1;g.strokeRect(R.x+.5,R.y+.5,R.w-1,R.h-1);
 g.imageSmoothingEnabled=false;g.drawImage(mapLayer(sc),mx,my,100,65);for(const o of OB[sc]||[])if(o.id=='mail'){g.fillStyle=FG.qready?'#ff4040':'#4a90e0';g.fillRect(mx+o.x*s,my+o.y*s,s,s)}
 const E=mapEnts(sc);for(const e of E)if(e.k!='npc'&&e.k!='ped')mapDot(e,mx+e.x*s,my+e.y*s,s);for(const e of E)if(e.k=='npc'||e.k=='ped')mapDot(e,mx+e.x*s,my+e.y*s,s);
 const act=wpActive();wpL().forEach(w=>{if(w.sc==sc){mapFlag(mx+(w.x+.5)*s,my+(w.y+.5)*s+2,w.c,7)}});
 const P=mapPlayerPos();if(Math.floor(performance.now()/400)%2||true)mapArrow(mx+P.x*s,my+P.y*s,mapFacing(),3.4,'#fff');
 g.fillStyle='rgba(0,0,0,.55)';g.fillRect(mx,my,34,10);wxIcon(wxKind(),mx+1,my-1);txt(wxTemp()+'°',mx+14,my+8,8,'#fff');
 if(act){const r=wpRoute(act);if(r&&r.hop){const ang=Math.atan2(r.hop[1]-(FG.y/32+.5),r.hop[0]-(FG.x/32+.5));mapArrow(R.x+10,R.y+78,ang,4.2,act.c);const d=Math.round(r.d);txt((act.n.length>8?act.n.slice(0,7)+'.':act.n)+' '+d+'t'+(r.cross?'>'+MAPN[act.sc].slice(0,3):''),R.x+18,R.y+81,8,'#fff')}}
 else txt(MAPN[sc]+' · M: map',R.x+R.w/2,R.y+81,8,UI.dim,'center')};
// ---- full-screen world map
const MAPL={ranch:{x:14,y:176},town:{x:224,y:176},mtn:{x:224,y:40}},MAPS=9;
