function drawChar(px,py,d,walk,col,id,label){const dx=S.x-CAMX-px,dy=S.y-CAMY-py;if(Math.abs(dx)+Math.abs(dy)<120)d=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);
 drawFig(g,px,py,d,'idle',(Date.now()/380|0)%4,{shirt:col,pants:'#3a3040',hair:(NP[id]||['#6a3a1a'])[0],hat:0});
 if(label){g.font='bold 10px monospace';const w=g.measureText(label).width+8;g.fillStyle='rgba(20,12,6,.8)';g.fillRect(px+16-w/2,py-14,w,13);txt(label,px+16,py-4,10,'#fff','center',1)}}
const go0=gfxObjs;gfxObjs=function(O,sx,sy){CAMX=sx;CAMY=sy;go0(O,sx,sy)};
